  `payRateFenMu` varchar(50) NULL COMMENT "付费率分母(上一步人数)",
  `arppu` varchar(50) NULL COMMENT "ARPPU",
  `unitPrice` varchar(50) NULL COMMENT "客单价",
  `rechargeAvg` decimal(16, 4) NULL COMMENT "人均充值次数",
  `totalArppu` varchar(50) NULL COMMENT "总消费ARPPU",
  `readCoinsArppu` varchar(50) NULL COMMENT "阅币消费ARPPU",
  `rechargePeopleNum` bigint(20) NULL COMMENT "充值人数",
  `rechargeNum` bigint(20) NULL COMMENT "充值次数",
  `rechargeAmount` varchar(50) NULL COMMENT "充值金额",
  `threePartiesAcount` varchar(50) NULL COMMENT "三方实收",
  `threePartiesPercent` varchar(50) NULL COMMENT "三方实收占比",
  `amountRate` varchar(50) NULL COMMENT "费率",
  `consumNum` bigint(20) NULL COMMENT "消费人数",
