  `consumeRate` varchar(50) NULL COMMENT "消费率",
  `adverArpu` varchar(50) NULL COMMENT "广告ARPU",
  `totalAdverArpu` varchar(50) NULL COMMENT "总广告ARPU",
  `adverUnlockRate` varchar(50) NULL COMMENT "广告解锁率",
  `adverUnlockRateFenzi` varchar(50) NULL COMMENT "广告解锁率分子(成功人数)",
