  `oneRechargePercentFenmu` decimal(20, 2) NULL COMMENT "单次充值占比分母(充值金额)",
  `dingYueAmountPercent` decimal(20, 6) NULL COMMENT "订阅金额占比",
  `dingYueAmountPercentFenzi` decimal(20, 2) NULL COMMENT "订阅金额占比分子(订阅金额)",
  `dingYueAmountPercentFenmu` decimal(20, 2) NULL COMMENT "订阅金额占比分母(充值金额)",
  `orderCreateRate` decimal(20, 6) NULL COMMENT "订单创建率",
