--
CREATE TABLE IF NOT EXISTS `ads_bi_trade_user_recharge_gear` (
  `dt` date NULL COMMENT "统计周期",
  `product_id` int(11) NULL COMMENT "产品id",
  `user_id` bigint(20) NULL COMMENT "用户id",
  `period_type` varchar(20) NULL COMMENT "统计周期类型,ctt/rmt,rmt(拉活用户)",
  `user_type` varchar(65533) NULL COMMENT "用户类型",
  `which_weeks` int(11) NULL COMMENT "对应日期的周数",
  `which_months` int(11) NULL COMMENT "对应日期的月份",
