  `reg_country` varchar(65533) NULL COMMENT "注册国家",
  `country_level` int(11) NULL COMMENT "国家等级",
  `mt` int(11) NULL COMMENT "平台",
  `corever` int(11) NULL COMMENT "core",
  `source` int(11) NULL COMMENT "3是付费 2是官网  1 是自然和其他 条件：source in ('fbs2s','facebook','tt','appleadservice','fixadinfo','sem','adwords') then 3 when source in ('officialsite','(not set)') then 2 else 1'",
  `shop_item` varchar(65533) NULL COMMENT "充值类型",
  `recharge_gear` decimal(18, 2) NULL COMMENT "充值档位（充值金额）",
  `is_first_charge` int(11) NULL COMMENT "是否首次充值 1：是 ，0：否",
  `charge_cnt` bigint(20) NULL COMMENT "充值次数",
  `before_charge` decimal(18, 2) NULL COMMENT "充值金额（分成前）",
  `after_charge` decimal(18, 2) NULL COMMENT "充值金额（分成后）",
  `etl_time` datetime NULL COMMENT "处理时间",
  `is_valid` int(11) NULL COMMENT "是否有效(1:是,0:否)",
  `is_first_subscription` int(11) NULL COMMENT "是否首次订阅(1:是,0:否)",
  `autorenew_times` int(11) NULL COMMENT "续订次数",
  `subscribe_status` int(11) NULL COMMENT "订阅状态(-1:试用,0:默认值,1:首次购买,2:续订)",
  `subpay_type` varchar(65533) NULL COMMENT "支付渠道",
  `user_ad_source` int(11) NULL COMMENT "广告投流用户：0：正常用户，1：vip投流用户",
  INDEX index_which_weeks (`which_weeks`) USING BITMAP COMMENT 'index_which_weeks',
  INDEX index_which_months (`which_months`) USING BITMAP COMMENT 'index_which_months'
) ENGINE=OLAP
DUPLICATE KEY(`dt`, `product_id`, `user_id`)
COMMENT "用户域登录阅读充值消耗汇总活跃表"
DISTRIBUTED BY HASH(`product_id`, `user_id`) BUCKETS 1
PROPERTIES (
"replication_num" = "3",
