  `dt` date NOT NULL COMMENT "统计日期",
  `md5_key` varchar(65533) NOT NULL COMMENT "md5_key",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `period_type` varchar(65533) NOT NULL COMMENT "统计周期类型,ctt/rmt,rmt(拉活用户)",
  `period_week` varchar(65533) NOT NULL COMMENT "统计周期，周二为每周的第一天，截止到下一周周一",
  `mt` varchar(65533) NOT NULL COMMENT "终端",
  `country_level` varchar(65533) NOT NULL COMMENT "国家等级，t1,t2,美国",
  `reg_language` varchar(65533) NOT NULL COMMENT "注册语言",
  `user_type` varchar(65533) NOT NULL COMMENT "用户类型",
  `user_value` varchar(65533) NOT NULL COMMENT "用户价值",
  `chl2` varchar(65533) NOT NULL COMMENT "初始渠道值",
  `chl` varchar(65533) NOT NULL COMMENT "最新渠道值",
  `source_chl` varchar(65533) NOT NULL COMMENT "最新引流渠道",
  `corever` int(11) NOT NULL COMMENT "core: 1,2",
  `reg_country` varchar(65533) NOT NULL COMMENT "注册国家",
  `dau` bigint(20) NULL COMMENT "日活",
  `recharge_amount` decimal(24, 6) NULL COMMENT "分成后充值金额,获得的货币数/100",
  `recharge_cnt` bigint(20) NULL COMMENT "充值用户数",
  `vip_recharge_amt` decimal(24, 6) NULL COMMENT "充值会员金额(除了100之后的)",
  `limit_free_amt` decimal(24, 6) NULL COMMENT "限免卡金额",
  `consume_money` decimal(24, 6) NULL COMMENT "付费货币消费金额",
  `consume_all` decimal(24, 6) NULL COMMENT "总消费金额(海剧：观看币和观看券，国剧：金豆)",
  `consume_money_cnt` bigint(20) NULL COMMENT "付费货币消费人数",
  `consume_all_cnt` bigint(20) NULL COMMENT "总消费人数(海剧：观看币和观看券，国剧：金豆)",
  `consume_user_pay_cnt` bigint(20) NULL COMMENT "付费消费人数((币或金豆)+会员+限免卡))",
  `consume_wide_all_cnt` bigint(20) NULL COMMENT "总消费人数((币或金豆)+券+会员+限免卡)",
  `recharge_item_amt` decimal(24, 6) NULL COMMENT "税前充值金额",
  `consume_pay_vip` decimal(24, 6) NULL COMMENT "超点消费金额",
  `consume_pay_vip_cnt` bigint(20) NULL COMMENT "超点消费人数",
  `ad_amt` decimal(24, 6) NULL COMMENT "广告收入金额",
  `natural_vip_recharge_amt` decimal(16, 2) NULL COMMENT "非引流SVIP充值金额",
  `natural_consume_money` decimal(16, 2) NULL COMMENT "非引流阅币消费金额",
  `natural_presented_money` decimal(16, 2) NULL COMMENT "非引流礼券消费金额",
  `natural_limit_free_amt` decimal(16, 2) NULL COMMENT "非引流限免卡消费金额",
  `natural_consume_money_all` decimal(16, 2) NULL COMMENT "非引流消费金额	",
  `natural_money_all` decimal(16, 2) NULL COMMENT "非引流付费消费金额",
  `etl_time` datetime NULL COMMENT "处理时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `md5_key`)
COMMENT "短剧周报"
PARTITION BY RANGE(`dt`)
