-- Table structure for table `ads_bi_wide_user_retention_info`
--
CREATE TABLE IF NOT EXISTS `ads_bi_wide_user_retention_info` (
  `dt` date NOT NULL COMMENT "统计日期,活跃日期",
  `md5_key` varchar(65533) NOT NULL COMMENT "主键md5key",
  `product_id` int(11) NULL COMMENT "产品id",
  `corever` int(11) NULL COMMENT "corever",
  `mt` int(11) NULL COMMENT "终端",
  `reg_country` varchar(512) NULL COMMENT "国家",
  `country_level` int(11) NULL COMMENT "国家等级",
  `current_language2` int(11) NULL COMMENT "注册语言",
  `source` int(11) NULL COMMENT "3是付费 2是官网  1 是自然和其他 条件：source in ('fbs2s','facebook','tt','appleadservice','fixadinfo','sem','adwords') then 3 when source in ('officialsite','(not set)') then 2 else 1",
  `user_period` int(11) NULL COMMENT "用户类型 1：新用户 2：活跃用户 3：rmt(拉活用户)",
  `is_pay` int(11) NULL COMMENT "是否付费 1：是 0：否",
  `chl2` varchar(512) NULL COMMENT "初始渠道值",
  `chl` varchar(512) NULL COMMENT "最新渠道值",
  `user_ad_source` int(11) NULL COMMENT "广告投流用户：0：正常用户，1：vip投流用户",
  `book_id` bigint(20) NULL COMMENT "广告bookid",
  `reg_days` int(11) NULL COMMENT "活跃时间与（注册时间，活跃时间，rmt时间差）",
  `retention_num` int(11) NULL COMMENT "留存人数",
  `etl_time` datetime NOT NULL COMMENT "数据清洗时间",
  INDEX index_user_period (`user_period`) USING BITMAP,
  INDEX index_current_language2 (`current_language2`) USING BITMAP COMMENT '注册语言索引',
  INDEX index_product_id (`product_id`) USING BITMAP COMMENT '产品id索引'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `md5_key`)
COMMENT "海阅、海剧，不同用户类型的留存数据"
PARTITION BY RANGE(`dt`)
(




































































