--
-- Table structure for table `ads_book_read_full_consume`
--
CREATE TABLE IF NOT EXISTS `ads_book_read_full_consume` (
  `dt` datetime NOT NULL COMMENT "日期",
  `book_id` bigint(20) NOT NULL COMMENT "书籍id",
  `site_id` int(11) NOT NULL COMMENT "书籍语言 ",
  `new_cid` int(11) NULL COMMENT "书籍分类id",
  `channel` int(11) NULL COMMENT "频道",
  `is_full` tinyint(4) NULL COMMENT "完结状态",
  `full_time` datetime NULL COMMENT "完结时间",
  `sexy2` int(11) NULL COMMENT "上架状态",
  `build_time` datetime NULL COMMENT "上架时间",
  `sign_type` int(11) NULL COMMENT "签约状态",
  `languageid` int(11) NULL COMMENT "书籍语言",
  `public_fontlength` int(11) NULL COMMENT "书籍发布总字数",
  `book_update_time` datetime NULL COMMENT "书籍更新时间",
  `consume_1d` int(11) NULL COMMENT "近1日阅币+礼券+赠送币+VIP消费消耗",
  `consume_7d` int(11) NULL COMMENT "近7日阅币+礼券+赠送币+VIP消费消耗",
  `consume_30d` int(11) NULL COMMENT "近30日阅币+礼券+赠送币+VIP消费消耗",
  `consume_td` int(11) NULL COMMENT "历史阅币+礼券+赠送币+VIP消费消耗",
  `read_1d` int(11) NULL COMMENT "近1日阅读人数",
  `read_7d` int(11) NULL COMMENT "近7日阅读人数",
  `read_30d` int(11) NULL COMMENT "近30日阅读人数",
  `read_td` int(11) NULL COMMENT "历史阅读人数",
  `update_word_count_1d` int(11) NULL COMMENT "近1日更新字数",
  `update_word_count_7d` int(11) NULL COMMENT "近7日更新字数",
  `update_word_count_30d` int(11) NULL COMMENT "近30日更新字数",
  `etl_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "etl清洗时间",
  `book_nature` int(11) NULL COMMENT "书籍来源 1：机翻 2：人工 3：原创 4：cp 5：原创拆章 6：翻译拆章 7：原创图书 8：有声书籍 9：cp翻译 0：未知",
  `score_type` int(11) NULL COMMENT "书籍评级  未评级 = 0, S = 1, A = 2, B = 3, C = 4",
  INDEX index_book_id (`book_id`) USING BITMAP COMMENT 'index_book_id'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `book_id`, `site_id`)
COMMENT "书籍维度阅读消耗数-全量消费类型"
DISTRIBUTED BY HASH(`dt`, `book_id`, `site_id`)
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "site_id, book_id",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

--
-- Table structure for table `ads_book_remarket_attribution_analysis_ed`
--
CREATE TABLE IF NOT EXISTS `ads_book_remarket_attribution_analysis_ed` (
  `dt` date NULL COMMENT "统计日期",
  `book_id` bigint(20) NULL COMMENT "书籍id",
  `product_id` int(11) NULL COMMENT "产品id",
  `ad_id` varchar(1000) NULL COMMENT "广告id",
  `install_num` int(11) NULL COMMENT "归因人数（这本书这个adid带来的用户数）",
  `charge_itemcount` decimal(18, 2) NULL COMMENT "充值金额",
  `charge_num` int(11) NULL COMMENT "充值人数",
  `charge_count` int(11) NULL COMMENT "充值次数（订单数）",
  `recharge_num` int(11) NULL COMMENT "充值次数>=2的人数",
  `charge_num_10` int(11) NULL COMMENT "充值>=10美金的用户数",
  `charge_count_10` int(11) NULL COMMENT "充值>=10美金的订单数",
  `read_num` int(11) NULL COMMENT "阅读人数",
  `read_num_2` int(11) NULL COMMENT "阅读大于2章的人数",
  `read_pay_num` int(11) NULL COMMENT "付费章节阅读uv",
  `consume_num` int(11) NULL COMMENT "消费uv",
  `consume_pay_num` int(11) NULL COMMENT "阅币消费uv",
  `read_num_5` int(11) NULL COMMENT "阅读大于5章的人数",
  `read_num_8` int(11) NULL COMMENT "阅读大于8章的人数",
  `consume_amount` int(11) NULL COMMENT "阅币+礼券消耗数量",
  `consume_pay_amount` int(11) NULL COMMENT "阅币消耗数量",
  `etl_time` datetime NULL COMMENT "数据更新时间",
  INDEX index_book_id (`book_id`) USING BITMAP COMMENT 'index_book_id'
) ENGINE=OLAP
DUPLICATE KEY(`dt`, `book_id`)
COMMENT "24小时广告书籍数据表-- 新用户：广告书籍的归因数据，按天统计这些书带来的充值、阅读人数、消耗数量等"
DISTRIBUTED BY HASH(`dt`, `book_id`) BUCKETS 1
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "dt, product_id, book_id",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

