--
-- Table structure for table `ads_sr_push_message_log`
--
CREATE TABLE IF NOT EXISTS `ads_sr_push_message_log` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `id` bigint(20) NOT NULL COMMENT "Id",
  `create_time` datetime NOT NULL COMMENT "插入时间",
  `user_id` bigint(20) NULL COMMENT "用户Id",
  `active_user_id` bigint(20) NULL COMMENT "活跃用户id",
  `prod_id` varchar(255) NULL COMMENT "产品ID",
  `mt` int(11) NULL COMMENT "平台",
  `title` varchar(65533) NULL COMMENT "标题",
  `token_id` bigint(20) NULL COMMENT "TokenId",
  `token` varchar(65533) NULL COMMENT "令牌",
  `body` varchar(65533) NULL COMMENT "内容",
  `customers` varchar(65533) NULL COMMENT "推送下发参数",
  `param` varchar(65533) NULL COMMENT "辅助参数",
  `batch_id` bigint(20) NULL COMMENT "批次Id",
  `state` int(11) NULL COMMENT "状态:0未入列1已入列2已出列3已推送4推送失败5token不存在6FCM有效投递7FCM送达8已发站内信",
  `update_time` datetime NULL COMMENT "更新时间",
  `push_response` varchar(65533) NULL COMMENT "推送结果",
  `push_type` int(11) NULL COMMENT "推送类型 1常规 2私信",
  `push_time` datetime NULL COMMENT "计划推送时间",
  `message_id` varchar(65533) NULL COMMENT "消息 ID 用于标识消息（FCM使用）",
  `token_type` int(11) NULL COMMENT "0友盟1FCM2华为",
  `task_type` int(11) NULL COMMENT "任务类型1Tag中台推送2全站推送3召回推送任务4章节更新推送",
  `image_url` varchar(65533) NULL COMMENT "",
  `is_silent` tinyint(4) NULL COMMENT "",
  `etl_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "ETL时间",
  INDEX index_productid (`product_id`) USING BITMAP COMMENT 'index_productid',
  INDEX index_state (`state`) USING BITMAP COMMENT 'index_state'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `id`, `create_time`)
COMMENT "push推送日志表"
PARTITION BY RANGE(`dt`)
