--
CREATE TABLE IF NOT EXISTS `ads_sv_material_grade_data_result` (
  `dt` date NULL COMMENT "更新日期，按西五区更新数据",
  `material_id` bigint(20) NULL COMMENT "素材任务id",
  `date_key` date NULL COMMENT "评级指标统计截止日期",
  `material_type` varchar(100) NULL COMMENT "素材类型：视频，图片",
