  `clicks` int(11) NULL COMMENT "当日点击互动",
  `link_clicks` int(11) NULL COMMENT "当日链接点击",
  `installs` int(11) NULL COMMENT "当日激活",
  `amount` decimal(16, 6) NULL COMMENT "当日H24收入",
  `grade_date` date NULL COMMENT "满足评级条件的首日:花费>50的日期，null说明没有",
  `first_date` date NULL COMMENT "首次投放日期",
  `days` int(11) NULL COMMENT "满足评级条件的第N天，0~3",
  `spend_dt_sum` decimal(16, 6) NULL COMMENT "评级首日到截止日期的累计花费",
  `spend_sum` decimal(16, 6) NULL COMMENT "截止当前累计花费",
  `impressions_sum` int(11) NULL COMMENT "截止当前累计展示量",
  `clicks_sum` int(11) NULL COMMENT "截止当前累计点击互动",
  `link_clicks_sum` int(11) NULL COMMENT "截止当前累计链接点击",
  `installs_sum` int(11) NULL COMMENT "截止当前累计激活",
  `amount_sum` decimal(16, 6) NULL COMMENT "截止当前累计H24收入",
  `level` int(11) NULL COMMENT "评级类型，1=日花费大于50的评级样本，2=不满足日花费大于50  但累计花费大于150的评级样本，99=无评级",
  `ctr_link` decimal(16, 6) NULL COMMENT "评级期间链接点击率",
  `cvr` decimal(16, 6) NULL COMMENT "评级期间CVR",
  `roas` decimal(16, 6) NULL COMMENT "评级期间ROAS",
  `ir` decimal(16, 6) NULL COMMENT "评级期间IR",
  `ctr_cvr` decimal(16, 6) NULL COMMENT "评级期间链接点击率",
  `spend` decimal(16, 6) NULL COMMENT "评级期间累计花费",
  `cpm` decimal(16, 6) NULL COMMENT "评级期间CPM",
  `ir_to1` decimal(16, 6) NULL COMMENT "IR，归一化",
  `cvr_to1` decimal(16, 6) NULL COMMENT "CVR，归一化",
  `ctr_cvr_to1` decimal(16, 6) NULL COMMENT "（CVR-CTR）的绝对值，归一化",
  `ln_spend_to1` decimal(16, 6) NULL COMMENT "ln（花费），归一化",
  `roas_to1` decimal(16, 6) NULL COMMENT "roas，归一化",
  `cpm_to1` decimal(16, 6) NULL COMMENT "log（CPM），归一化",
  `grade_score` decimal(16, 6) NULL COMMENT "评级得分，满分是5分",
  `grade` varchar(200) NULL COMMENT "分级",
  `score_createtime` datetime NULL COMMENT "人工打分时间",
  `creator` varchar(200) NULL COMMENT "打分人名称",
  `avg_score` decimal(16, 6) NULL COMMENT "人工打分",
  `etl_tm` datetime NULL COMMENT "清洗时间"
) ENGINE=OLAP
DUPLICATE KEY(`dt`, `material_id`)
COMMENT "海剧素材分级表-v2"
DISTRIBUTED BY HASH(`dt`, `material_id`) BUCKETS 3
PROPERTIES (
"replication_num" = "3",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"storage_medium" = "SSD",
"compression" = "ZSTD"
);



