--
CREATE TABLE IF NOT EXISTS `ads_wide_book_read_consume_info_a` (
  `dt` date NOT NULL COMMENT "统计时间",
  `book_id` bigint(20) NOT NULL COMMENT "书籍id",
  `book_name` varchar(255) NULL COMMENT "书籍名称",
  `site_id2` int(11) NULL COMMENT "书籍语言使用site_id2字段；默认 繁体：333 简体：777；两者书籍会有重复部分 ",
  `language_id` int(11) NULL COMMENT "语言",
  `create_time` datetime NULL COMMENT "创建时间",
  `update_time` datetime NULL COMMENT "更新时间",
  `book_nature` int(11) NULL COMMENT "书籍来源 1：机翻 2：人工 3：原创 4：cp 5：原创拆章 6：翻译拆章 7：原创图书 8：有声书籍 9：cp翻译 0：未知",
  `sign_type` int(11) NULL COMMENT "签约类型 独家：0 买断， 1 A签；非独家：2 B签； 未签约：-1",
  `channel` int(11) NULL COMMENT "频道0:男频 1:女频",
  `is_full` tinyint(4) NULL COMMENT "是否完本",
  `price_per_thousand` int(11) NULL COMMENT "千字价格",
  `new_cid` int(11) NULL COMMENT "书籍分类id",
  `new_cname` varchar(100) NULL COMMENT "分类名称",
  `sexy2` int(11) NULL COMMENT "书籍上架、下架判断：字段来源novel_book; Sexy2 >= 4 为下架状态，<4 为上架，其中，Sexy涉黄等级 4软下架 5强制下架 ,0 未涉黄;其他具体数字只是涉黄的分级，没有太多参考意义",
  `normal_chapter_num_f` int(11) NULL COMMENT "发布总章节数",
  `build_time` datetime NULL COMMENT "书籍上传时间",
  `font_length` int(11) NULL COMMENT "书籍总字数（包含未发布的）",
  `full_time` datetime NULL COMMENT "完本时间",
  `public_fontlength` int(11) NULL COMMENT "发布的书籍字数（来源nove_book的length)",
  `author_id` bigint(20) NULL COMMENT "作者Id",
  `author_name` varchar(500) NULL COMMENT "作者名称",
  `Free_ChapterNum` int(11) NULL COMMENT "免费章节数(无效字段）",
  `latest_update_time` datetime NULL COMMENT "章节最新更新时间",
  `read_unt_td` bigint(20) NULL COMMENT "阅读人数",
  `read_pay_unt_td` bigint(20) NULL COMMENT "付费章节阅读人数",
  `read_chapter_cnt_td` bigint(20) NULL COMMENT "阅读章节数",
  `read_pay_chapter_cnt_td` bigint(20) NULL COMMENT " 阅读付费章节数",
  `read_times_td` bigint(20) NULL COMMENT "阅读时长",
  `consume_unt_td` bigint(20) NULL COMMENT "消耗人数",
  `consume_amt_td` bigint(20) NULL COMMENT "消耗数量",
  `consume_cnt_td` bigint(20) NULL COMMENT "消耗次数",
  `consume_chapter_cnt_td` bigint(20) NULL COMMENT "消耗章节数",
  `consume_money_unt_td` bigint(20) NULL COMMENT "阅币消耗人数",
  `consume_money_amt_td` bigint(20) NULL COMMENT "消耗阅币数量",
  `consume_money_cnt_td` bigint(20) NULL COMMENT "消耗阅币次数",
  `consume_money_chapter_cnt_td` int(11) NULL COMMENT "消耗阅币章节数 ",
  `consume_gift_unt_td` bigint(20) NULL COMMENT "礼券消耗人数",
  `consume_gift_amt_td` bigint(20) NULL COMMENT "消耗礼券数量",
  `consume_gift_cnt_td` bigint(20) NULL COMMENT "消耗礼券次数",
  `consume_gift_chapter_cnt_td` bigint(20) NULL COMMENT "消耗礼券章节数 ",
  `etl_time` datetime NULL COMMENT "etl清洗时间 "
) ENGINE=OLAP
PRIMARY KEY(`dt`, `book_id`)
COMMENT "书籍维度累计阅读消耗指标宽表"
