--
-- Table structure for table `ads_wide_short_video_ed`
--
CREATE TABLE IF NOT EXISTS `ads_wide_short_video_ed` (
  `dt` date NOT NULL COMMENT "统计日期，昨日",
  `product_id` smallint(6) NOT NULL COMMENT "产品名称",
  `user_id` bigint(20) NOT NULL COMMENT "用户id",
  `sex` smallint(6) NULL COMMENT "性别",
  `reg_tm` datetime NULL COMMENT "用户的注册时间",
  `mt` smallint(6) NULL COMMENT "平台 0未知 1iphone 4安卓 9书城",
  `mt2` smallint(6) NULL COMMENT "注册时平台 0未知 1iphone 4安卓 9书城",
  `corever` smallint(6) NULL COMMENT "当前core",
  `corever2` smallint(6) NULL COMMENT "注册时core",
  `app_ver` varchar(65533) NULL COMMENT "app版本",
  `ver` bigint(20) NULL COMMENT "客户端版本号",
  `current_language` bigint(20) NULL COMMENT "用户当前语言",
  `current_language2` bigint(20) NULL COMMENT "注册时语言",
  `reg_country` varchar(65533) NULL COMMENT "注册时国家，不会变化",
  `lst_source_chl` varchar(65533) NULL COMMENT "最新渠道值",
  `is_bound_email` smallint(6) NULL COMMENT "是否绑定邮箱 1:是 0：否",
  `consume_amt` decimal(20, 6) NULL COMMENT "消耗货币数",
  `consume_cnt` bigint(20) NULL COMMENT "消耗次数(消耗为0不算)",
  `consume_epis_bitmap` bitmap NULL COMMENT "消耗剧集bitmap(剧id+集序号,消耗为0不算)",
  `consume_money_amt` decimal(20, 6) NULL COMMENT "消耗观看币(代币)数",
  `consume_money_cnt` bigint(20) NULL COMMENT "消耗观看币(代币)次数",
  `consume_money_epis_bitmap` bitmap NULL COMMENT "观看币(代币)消耗剧集bitmap(剧id+集序号)",
  `consume_cert_amt` decimal(20, 6) NULL COMMENT "消耗观看券(赠币)数",
  `consume_cert_cnt` bigint(20) NULL COMMENT "消耗观看券(赠币)次数",
  `consume_cert_epis_bitmap` bitmap NULL COMMENT "观看币(代币)消耗剧集bitmap(剧id+集序号)",
  `pay_amt` decimal(24, 8) NULL COMMENT "分成前总充值（不考虑退款因素）",
  `received_amt` decimal(24, 8) NULL COMMENT "分成后总充值（不考虑退款因素）",
  `refund_amt` decimal(24, 8) NULL COMMENT "总退款(分成前,存在跨天退款的情况)",
  `refund_real_amt` decimal(24, 8) NULL COMMENT "总退款(分成后，存在跨天退款的情况)",
  `pay_cnt` bigint(20) NULL COMMENT "总充值次数（不考虑退款因素）",
  `refund_cnt` bigint(20) NULL COMMENT "总退款次数",
  `max_pay_amt` decimal(24, 8) NULL COMMENT "当天的分成前最大充值金额（不考虑退款因素)",
  `min_pay_amt` decimal(24, 8) NULL COMMENT "当天的分成前最小充值金额（不考虑退款因素）",
  `login_cnt` bigint(20) NULL COMMENT "登录次数",
  `watch_epis_bitmap` bitmap NULL COMMENT "观看剧集bitmap(剧id+集序号)",
  `epis_watch_cnt` bigint(20) NULL COMMENT "剧集有效观看数据(一次观看开始、结束各产生一条，计算次数需要除以2并上浮取整)",
  `is_like_cnt` bigint(20) NULL COMMENT "总退款(分成前,存在跨天退款的情况)",
  `is_like_epis_bitmap` bitmap NULL COMMENT "点赞剧集bitmap(剧id+集序号)",
  `etl_time` datetime NOT NULL COMMENT "数据清洗时间",
  INDEX index_product_id (`product_id`) USING BITMAP COMMENT '产品id索引'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `user_id`)
COMMENT "海外短剧用户业务指标1日汇总表"
PARTITION BY RANGE(`dt`)
