--
-- Table structure for table `ads_wide_short_video_epis_a`
--
CREATE TABLE IF NOT EXISTS `ads_wide_short_video_epis_a` (
  `dt` date NOT NULL COMMENT "统计日期，昨日",
  `series_id` bigint(20) NOT NULL COMMENT "剧id",
  `epis_num` smallint(6) NOT NULL COMMENT "剧集序号",
  `epis_id` bigint(20) NULL COMMENT "最新剧集id",
  `series_name` varchar(65533) NULL COMMENT "剧名名称",
  `series_language` smallint(6) NULL COMMENT "剧语言",
  `series_tp` varchar(65533) NULL COMMENT "短剧分类",
  `cooperate_type` smallint(6) NULL COMMENT "合作方式(1买断、2分成、3保底分成)",
  `series_code` varchar(65533) NULL COMMENT "代码",
  `is_free` smallint(6) NULL COMMENT "是否免费 1：是 0： 否",
  `epis_length` bigint(20) NULL COMMENT "视频长度",
  `epis_amount` bigint(20) NULL COMMENT "剧集价位(代币/赠币)",
  `consume_user_bitmap` bitmap NULL COMMENT "累计消费用户bitmap",
  `consume_amt` decimal(38, 6) NULL COMMENT "总消耗数量",
  `consume_cnt` bigint(20) NULL COMMENT "总消耗次数",
  `consume_money_user_bitmap` bitmap NULL COMMENT "累计观看币消耗用户bitmap",
  `consume_money_amt` decimal(38, 6) NULL COMMENT "累计观看币消耗数量",
  `consume_money_cnt` bigint(20) NULL COMMENT "累计观看币消耗次数",
  `consume_cert_user_bitmap` bitmap NULL COMMENT "累计观看券消耗用户bitmap",
  `consume_cert_amt` decimal(38, 6) NULL COMMENT "累计观看券消耗数量",
  `consume_cert_cnt` bigint(20) NULL COMMENT "累计观看券消耗次数",
  `watch_user_bitmap` bitmap NULL COMMENT "累计观看用户bitmap",
  `watch_cnt` bigint(20) NULL COMMENT "剧集有效观看数据(一次观看开始、结束各产生一条，计算次数需要除以2并上浮取整,值会有误差)",
  `is_like_user_bitmap` bitmap NULL COMMENT "累计点赞用户bitmap",
  `etl_time` datetime NOT NULL COMMENT "数据清洗时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `series_id`, `epis_num`)
