--
-- Table structure for table `event_detail_aggregate_count`
--
CREATE MATERIALIZED VIEW `event_detail_aggregate_count` (`event`, `project_id`, `$lib`, `app_core_ver`, `app_lang_id`, `dt`, `line_count`, `repeat_count`)
PARTITION BY (`dt`)
DISTRIBUTED BY HASH(`event`)
REFRESH ASYNC EVERY(INTERVAL 10 DAY)
PROPERTIES (
"replicated_storage" = "true",
"replication_num" = "3",
"storage_medium" = "HDD"
)
AS SELECT `event_detail_aggregate_hour`.`event`, `event_detail_aggregate_hour`.`project_id`, `event_detail_aggregate_hour`.`$lib`, `event_detail_aggregate_hour`.`app_core_ver`, `event_detail_aggregate_hour`.`app_lang_id`, date_trunc('day', `event_detail_aggregate_hour`.`time_hour`) AS `dt`, sum(`event_detail_aggregate_hour`.`line_count`) AS `line_count`, sum(`event_detail_aggregate_hour`.`repeat_count`) AS `repeat_count`
FROM `analytics_point`.`event_detail_aggregate_hour`
GROUP BY `event_detail_aggregate_hour`.`event`, `event_detail_aggregate_hour`.`project_id`, `event_detail_aggregate_hour`.`$lib`, `event_detail_aggregate_hour`.`app_core_ver`, `event_detail_aggregate_hour`.`app_lang_id`, `dt`;

