  `max_try_times` tinyint(4) NULL COMMENT "max try times",
  `failure_strategy` tinyint(4) NULL COMMENT "failure strategy. 0:end the process when node failed,1:continue running the other nodes when node failed",
  `warning_type` tinyint(4) NULL COMMENT "warning type. 0:no warning,1:warning if process success,2:warning if process failed,3:warning if success",
  `warning_group_id` int(11) NULL COMMENT "warning group id",
