  `process_instance_id` int(11) NULL COMMENT "process instance id",
  `state` tinyint(4) NULL COMMENT "Status: 0 commit succeeded,1 running,2 prepare to pause,,3 pause,,4 prepare to stop,,5 stop,,6 fail,,7 succeed,,8 need fault tolerance,,9 kill,,10 wait for thread,,11 wait for dependency to complete",
  `submit_time` datetime NULL COMMENT "task submit time",
  `start_time` datetime NULL COMMENT "task start time",
  `end_time` datetime NULL COMMENT "task end time",
  `host` varchar(65533) NULL COMMENT "host of task running on",
  `execute_path` varchar(65533) NULL COMMENT "task execute path in the host",
  `log_path` varchar(65533) NULL COMMENT "task log path",
  `alert_flag` tinyint(4) NULL COMMENT "whether alert",
  `retry_times` int(11) NULL COMMENT "task retry times",
  `pid` int(11) NULL COMMENT "pid of task",
  `app_link` varchar(65533) NULL COMMENT "yarn app id",
  `task_params` varchar(65533) NULL COMMENT "job custom parameters",
  `flag` tinyint(4) NULL COMMENT "0 not available,1 available",
  `retry_interval` int(11) NULL COMMENT "retry interval when task failed ",
  `max_retry_times` int(11) NULL COMMENT "max retry times",
  `task_instance_priority` int(11) NULL COMMENT "task instance priority:0 Highest,1 High,2 Medium,3 Low,4 Lowest",
  `worker_group` varchar(65533) NULL COMMENT "worker group id",
  `environment_code` bigint(20) NULL COMMENT "environment code",
  `environment_config` varchar(65533) NULL COMMENT "this config contains many environment variables config",
  `executor_id` int(11) NULL COMMENT "",
  `first_submit_time` datetime NULL COMMENT "task first submit time",
  `delay_time` int(11) NULL COMMENT "task delay execution time",
  `var_pool` varchar(65533) NULL COMMENT "var_pool",
  `task_group_id` int(11) NULL COMMENT "task group id",
  `dry_run` tinyint(4) NULL COMMENT "dry run flag: 0 normal,1 dry run",
  `cpu_quota` int(11) NOT NULL COMMENT "cpuQuota(%): -1:Infinity",
  `memory_max` int(11) NOT NULL COMMENT "MemoryMax(MB): -1:Infinity",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `id`)
COMMENT "海豚starrocks任务实例表"
DISTRIBUTED BY HASH(`dt`, `id`) BUCKETS 1
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "dt",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

