  `is_full` tinyint(4) NULL COMMENT "是否完本  0:连载（未完本） 1：完本 3:完本打包队列 4:完本打包成功 5：完本打包失败 6：完本不打包 7：图书打包 ",
  `sexy2` int(11) NULL COMMENT "涉黄等级",
  `Free_Chapter_Num` int(11) NULL COMMENT "是否收费章节，1：是 0：否",
  `create_time` datetime NULL COMMENT "创建时间",
  `etl_time` datetime NULL COMMENT "数据更新时间",
  INDEX index_site_id (`site_id`) USING BITMAP COMMENT 'index_site_id'
) ENGINE=OLAP
PRIMARY KEY(`book_id`, `site_id`, `serial_number`, `chapter_id`)
COMMENT "书籍章节信息表"
DISTRIBUTED BY HASH(`book_id`, `site_id`, `serial_number`, `chapter_id`) BUCKETS 70
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "book_id",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

