--
CREATE TABLE IF NOT EXISTS `dim_date` (
  `date_id` varchar(50) NOT NULL COMMENT "日期(yyyymmdd)",
  `datestr` varchar(50) NOT NULL COMMENT "日期(yyyy-mm-dd)",
  `date_name` varchar(50) NULL COMMENT "日期名称中文",
  `weekid` int(11) NULL COMMENT "周(0-6,周日~周六)",
  `week_cn_name` varchar(50) NULL COMMENT "周_名称_中文",
  `week_en_name` varchar(50) NULL COMMENT "周_名称_英文",
  `week_en_nm` varchar(50) NULL COMMENT "周_名称_英文缩写",
  `yearmonthid` varchar(50) NULL COMMENT "月份id(yyyymm)",
  `yearmonthstr` varchar(50) NULL COMMENT "月份(yyyy-mm)",
  `monthid` int(11) NULL COMMENT "月份id（1-12）",
  `monthstr` varchar(50) NULL COMMENT "月份",
  `month_cn_name` varchar(50) NULL COMMENT "月份名称_中文",
  `month_en_name` varchar(50) NULL COMMENT "月份名称_英文",
  `month_en_nm` varchar(50) NULL COMMENT "月份名称_简写_英文",
  `quarterid` int(11) NULL COMMENT "季度id（1-4）",
  `quarterstr` varchar(50) NULL COMMENT "季度名称",
  `quarter_cn_name` varchar(50) NULL COMMENT "季度名称_中文",
  `quarter_en_name` varchar(50) NULL COMMENT "季度名称_英文",
  `quarter_cn_nm` varchar(50) NULL COMMENT "季度名称_简写中文",
  `quarter_en_nm` varchar(50) NULL COMMENT "季度名称_简写英文",
  `yearid` int(11) NULL COMMENT "年份id",
  `year_cn_name` varchar(50) NULL COMMENT "年份名称_中文",
  `year_en_name` varchar(50) NULL COMMENT "年份名称_英文",
  `month_start_date` varchar(50) NULL COMMENT "当月1号(yyyy-mm-dd)",
  `month_end_date` varchar(50) NULL COMMENT "当月最后日期(yyyy-mm-dd)",
  `month_timespan` int(11) NULL COMMENT "月跨天数",
  `week_of_year` int(11) NULL COMMENT "当年第几周",
  `workday_flag` varchar(50) NULL COMMENT "是否工作日(周一至周五Y，否则:N)",
  `weekend_flag` varchar(50) NULL COMMENT "是否周末(周六和周日Y,否则:N)",
  `china_holiday_flag` varchar(50) NULL COMMENT "是否中国节假日Y",
  `china_holiday_name` varchar(50) NULL COMMENT "补班名称/节假日名称",
  `china_workday_flag` varchar(50) NULL COMMENT "是否工作日(周一至周五并且不是中国法定节假日或者节假日前后的补班Y，否则:N)"
) ENGINE=OLAP
PRIMARY KEY(`date_id`, `datestr`)
COMMENT "书籍作者维度表"
DISTRIBUTED BY HASH(`datestr`) BUCKETS 3
PROPERTIES (
"replication_num" = "3",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

