CREATE TABLE IF NOT EXISTS `dim_user_all_info` (
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `user_id` bigint(20) NOT NULL COMMENT "用户id",
  `account` varchar(65533) NULL COMMENT "账户id",
  `nick` varchar(65533) NULL COMMENT "昵称",
  `sex` int(11) NULL COMMENT "性别0未知 1男 2女 3保密",
  `create_tm_account` datetime NULL COMMENT "用户的注册时间",
  `last_login_tm` datetime NULL COMMENT "上次登录时间",
  `chl` varchar(65533) NULL COMMENT "渠道值",
  `mt` int(11) NULL COMMENT "平台 0未知 1iphone 4安卓 9书城",
  `imei` varchar(65533) NULL COMMENT "国际移动设备识别码",
  `imsi` varchar(65533) NULL COMMENT "国际移动用户识别码",
  `mac` varchar(65533) NULL COMMENT "硬件地址",
  `money` int(11) NULL COMMENT "当前剩余阅币",
  `phone` varchar(65533) NULL COMMENT "手机号",
  `device_guid` varchar(65533) NULL COMMENT "设备guid",
  `device_token` varchar(65533) NULL COMMENT "关联的设备推送token",
  `email` varchar(65533) NULL COMMENT "电子邮箱",
  `is_has_charge` tinyint(4) NULL COMMENT "是否充过值",
  `province` varchar(65533) NULL COMMENT "省份",
  `city` varchar(65533) NULL COMMENT "城市",
  `birthday` datetime NULL COMMENT "生日",
  `country` varchar(65533) NULL COMMENT "国家，会变化，从用户最新ip地址解析而来",
  `prod_id` varchar(65533) NULL COMMENT "产品id",
  `code` varchar(65533) NULL COMMENT "邀请码,邀请新用户注册的",
  `gift_money` int(11) NULL COMMENT "礼券数量",
  `award_money` int(11) NULL COMMENT "赠送币数量",
  `chl2` varchar(65533) NULL COMMENT "初始渠道值",
  `ip` varchar(65533) NULL COMMENT "用户最后一次使用ip",
  `point` int(11) NULL COMMENT "积分",
  `app_ver` varchar(65533) NULL COMMENT "app版本",
  `ver` int(11) NULL COMMENT "客户端版本号",
  `id_fa` varchar(65533) NULL COMMENT "广告主标识符",
  `ad_id` varchar(65533) NULL COMMENT "deeplink 统计需要： 广告id",
  `ad_type` int(11) NULL COMMENT "deeplink 统计需要： 广告类型 0=facebook 1=adwords",
  `android_id` varchar(65533) NULL COMMENT "deeplink 统计需要 安卓id",
  `reg_ip` varchar(65533) NULL COMMENT "注册ip",
  `reg_country` varchar(65533) NULL COMMENT "注册时国家，不会变化",
  `is_has_bound_email` tinyint(4) NULL COMMENT "是否绑定过邮箱",
  `email_bound_status` tinyint(4) NULL COMMENT "邮箱绑定状态 true 已绑定 false 未绑定",
  `jifen` int(11) NULL COMMENT "积分",
  `corever` int(11) NULL COMMENT "版本号",
  `is_firebase` tinyint(4) NULL COMMENT "deeplink 是否是firebase数据",
  `app_id` int(11) NULL COMMENT "项目id，core，语言",
  `app_id2` int(11) NULL COMMENT "首次登陆的appid",
  `current_language` int(11) NULL COMMENT "用户当前语言",
  `row_update_tm_account` datetime NULL COMMENT "行数据更新了就会变更时间",
  `android_id_fordevice_guid` varchar(65533) NULL COMMENT "安卓设备id",
  `mt2` int(11) NULL COMMENT "注册时的终端",
  `corever2` int(11) NULL COMMENT "注册时的corever",
  `deep_link_platform_account` int(11) NULL COMMENT "deeplink来源平台：-1不是动态链接，0：fb，1：firebase，2：appsflyer",
  `reg_country2` varchar(65533) NULL COMMENT "注册国家，从华总的kochava来的，if_user_installreferrer,会变化",
  `book_id_account` varchar(65533) NULL COMMENT "广告bookid",
  `unique_cdreader_id` varchar(65533) NULL COMMENT "注册时设备号",
  `current_language2` int(11) NULL COMMENT "注册时语言",
  `is_has_change_lang` int(11) NULL COMMENT "是否修改过，注册时候的语言",
  `ads_type` varchar(60) NULL COMMENT "用户广告标签ADSTYPE",
  `ads_quality` int(11) NULL COMMENT "用户广告标签",
  `default_into_page_type` int(11) NULL COMMENT "默认进入页面",
  `default_into_page_time` datetime NULL COMMENT "分组时间",
  `is_negative_user` int(11) NULL COMMENT "是否白嫖用户",
  `remarketing_time` datetime NULL COMMENT "再召回时间",
  `low_vip_seconds_start_tm` datetime NULL COMMENT "vip活动赠送开始时间",
  `low_vip_expire_tm` datetime NULL COMMENT "会员过期时间",
  `low_vip_expire_time_seconds` bigint(20) NULL COMMENT "会员过期时间,vip活动赠送的剩余秒数",
  `last_buy_bonussign_card_tm` datetime NULL COMMENT "上次购买福利包时间",
  `last_buybonussign_cardplus_tm` datetime NULL COMMENT "上次购买plus福利包时间",
  `bonussign_card_tm` datetime NULL COMMENT "阅币福利包到期时间",
  `bonussign_cardplus_tm` datetime NULL COMMENT "阅币福利包plus到期时间",
  `user_maxcharge_amount` decimal(10, 0) NULL COMMENT "最高充值档位",
  `level` varchar(65533) NULL COMMENT "reg_country注册时国家等级",
  `user_type` varchar(100) NULL COMMENT "1IAA 2纯白嫖 3付费白嫖 4非白嫖",
  `etl_tm` datetime NULL COMMENT "",
  `ram` int(11) NULL COMMENT "手机内存",
  `sys_releasever` varchar(65533) NULL COMMENT "固件版本",
  `device` varchar(65533) NULL COMMENT "设备号",
  `brand` varchar(65533) NULL COMMENT "手机品牌",
  `continue_sign_num` int(11) NULL COMMENT "连续签到天数",
  `medal` int(11) NULL COMMENT "勋章数",
  `medal_min_expire_time` datetime NULL COMMENT "勋章最早过期时间",
  `daily_jifen_to_gift_flag` double NULL COMMENT "每日积分自动兑换礼券标记",
  `has_invite_friends` int(11) NULL COMMENT "是否有邀请",
  `total_read_times` bigint(20) NULL COMMENT "",
  `last_country_name` varchar(65533) NULL COMMENT "",
  `user_ad_source` int(11) NULL COMMENT "广告投流用户：0：正常用户，1：vip投流用户",
  INDEX index_productid (`product_id`) USING BITMAP COMMENT 'index_productid'
) ENGINE=OLAP
PRIMARY KEY(`product_id`, `user_id`)
COMMENT "用户维度信息表"
DISTRIBUTED BY HASH(`product_id`, `user_id`) BUCKETS 240
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "user_id, create_tm_account",
"colocate_with" = "productid_userid_group",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

