  `proofread_price_rmb_today` decimal(24, 8) NULL COMMENT "当日二校成本(人民币)",
  `proofread_price_today` decimal(24, 8) NULL COMMENT "当日二校成本(美金)",
  `publish_length_today` int(11) NOT NULL COMMENT "当日发布字数",
  `add_num` varchar(250) NULL COMMENT "加更配置",
  `week_rate` decimal(19, 2) NOT NULL COMMENT "七天费率",
  `month_rate` decimal(19, 2) NOT NULL COMMENT "三十天费率",
  `total_rate` decimal(19, 2) NOT NULL COMMENT "合计费率",
  `book_code` varchar(250) NULL COMMENT "书籍代号",
  `interpreter_start_time` datetime NULL COMMENT "质检开始时间",
  `interpreter_end_time` datetime NULL COMMENT "质检结束时间",
