  `interpreter_reality_count` decimal(19, 2) NOT NULL COMMENT "质检实际完成量",
  `foreign_start_time` datetime NULL COMMENT "一校开始时间",
  `foreign_end_time` datetime NULL COMMENT "一校结束时间",
  `foreign_plan_count` decimal(19, 2) NOT NULL COMMENT "一校计划完成量",
  `foreign_reality_count` decimal(19, 2) NOT NULL COMMENT "一校实际完成量",
  `stop_time` datetime NULL COMMENT "停更时间",
