--
-- Table structure for table `dwd_market_center_group_info`
--
CREATE TABLE IF NOT EXISTS `dwd_market_center_group_info` (
  `dt` date NOT NULL COMMENT "日期",
  `info_id` bigint(20) NOT NULL COMMENT "",
  `user_id` bigint(20) NOT NULL COMMENT "",
  `group_id` int(11) NOT NULL COMMENT "",
  `lang_id` int(11) NOT NULL COMMENT "",
  `create_tm` datetime NOT NULL COMMENT "",
  `end_tm` datetime NULL COMMENT "",
  `start_tm` datetime NULL COMMENT "",
  `second_lang_id` int(11) NOT NULL DEFAULT "0" COMMENT "二级语言",
  `tag_id` int(11) NOT NULL COMMENT "tag自增id",
  `name` varchar(255) NOT NULL COMMENT "标签名称",
  `tag_lang_id` int(11) NOT NULL COMMENT "语言 1 :cn  n2 :ft  n3 :en  n4 :sp  n5 :pt  n6 :fr  n7 :ru  n9 :jp...",
  `status` tinyint(4) NOT NULL COMMENT "状态",
  `tag_create_tm` datetime NOT NULL COMMENT "创建时间",
  `update_tm` datetime NULL COMMENT "修改时间",
  `code` varchar(50) NULL COMMENT "人群包标识",
  `is_sync` tinyint(4) NULL COMMENT "是否同步app",
  `group_type` int(11) NOT NULL COMMENT "人群包类型 1: 静态包_导入uid  n2: 静态包_系统生成  n3: 动态包_系统生成  n4: 特殊人群包_系统生成",
  `group_sync_tm` datetime NULL COMMENT "同步时间",
  `group_execution_tm` datetime NULL COMMENT "执行时间",
  `tag_second_lang_id` int(11) NOT NULL COMMENT "二级语言",
  `app_id_account` int(11) NULL COMMENT "项目id，core，语言",
  `mt` int(11) NULL COMMENT "平台 0未知 1iphone 4安卓 9书城",
  `is_has_charge` tinyint(4) NULL COMMENT "是否充过值",
  `corever` int(11) NULL COMMENT "版本号",
  `current_language` int(11) NULL COMMENT "用户当前语言",
  `current_language2` int(11) NULL COMMENT "注册时语言",
  `reg_country` varchar(65533) NULL COMMENT "注册时国家",
  `regdate` datetime NULL COMMENT "用户的注册时间",
  `prod_id` varchar(65533) NULL COMMENT "产品id",
  `device_guid` varchar(65533) NULL COMMENT "设备guid",
  `app_ver` varchar(65533) NULL COMMENT "app版本",
  `ver` int(11) NULL COMMENT "客户端版本号",
  `ads_type` varchar(60) NULL COMMENT "用户广告标签adstype",
  `ads_quality` int(11) NULL COMMENT "用户广告标签",
  `is_negative_user` int(11) NULL COMMENT "是否白嫖用户",
  `etl_tm` datetime NULL COMMENT ""
) ENGINE=OLAP
PRIMARY KEY(`dt`, `info_id`)
COMMENT "OLAP"
PARTITION BY RANGE(`dt`)
