--
-- Table structure for table `dwd_market_puzzleactuserrecord`
--
CREATE TABLE IF NOT EXISTS `dwd_market_puzzleactuserrecord` (
  `dt` date NOT NULL COMMENT "日期",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `puzzleactuserrecord_id` bigint(20) NOT NULL COMMENT "",
  `act_id` int(11) NULL COMMENT "",
  `pid` bigint(20) NULL COMMENT "",
  `img_id` int(11) NULL COMMENT "",
  `type` int(11) NULL COMMENT "",
  `token` varchar(150) NULL COMMENT "",
  `img_pre_result` varchar(1500) NULL COMMENT "",
  `img_result` varchar(1500) NULL COMMENT "",
  `comlete_status` int(11) NULL COMMENT "",
  `reward_status` int(11) NULL COMMENT "",
  `puzzleactuserrecord_add_tm` datetime NULL COMMENT "",
  `update_tm` datetime NULL COMMENT "",
  `power` int(11) NULL COMMENT "",
  `puzzleact_id` bigint(20) NOT NULL COMMENT "",
  `act_name` varchar(955) NOT NULL COMMENT "名称",
  `rule` varchar(955) NOT NULL COMMENT "规则",
  `positon` int(11) NOT NULL COMMENT "位置0 h5活动页,1冷却弹窗",
  `status` int(11) NOT NULL COMMENT "状态 0关闭 1开启",
  `powermax` int(11) NOT NULL COMMENT "体力上限",
  `third_multwo_power` int(11) NOT NULL COMMENT "3*2体力消耗",
  `third_mul_third_power` int(11) NOT NULL COMMENT "3*3体力消耗",
  `third_mul_four_power` int(11) NOT NULL COMMENT "3*4体力消耗",
  `third_mul_two_tm` int(11) NOT NULL COMMENT "3*2时长",
  `third_mul_third_tm` int(11) NOT NULL COMMENT "3*3时长",
  `third_mul_four_tm` int(11) NOT NULL COMMENT "3*4时长",
  `repower_tm` int(11) NOT NULL COMMENT "体力回复次数",
  `repowe_num` int(11) NOT NULL COMMENT "回复体力值",
  `repower_jifen` int(11) NOT NULL COMMENT "回复体力积分",
  `repowe_num_byjifen` int(11) NOT NULL COMMENT "积分回复体力",
  `retime_byad_count` int(11) NOT NULL COMMENT "广告续时次数",
  `retime_byad_tm` int(11) NOT NULL COMMENT "广告续时时间",
  `language` int(11) NOT NULL COMMENT "语言",
  `puzzleact_add_tm` datetime NOT NULL COMMENT "添加时间",
  `four_mul_four_power` int(11) NOT NULL DEFAULT "0" COMMENT "4*4体力消耗",
  `four_mul_four_tm` int(11) NOT NULL DEFAULT "0" COMMENT "4*4时长",
  `unlock_num` int(11) NOT NULL DEFAULT "0" COMMENT "解锁关卡数",
  `pk_jifen` int(11) NOT NULL DEFAULT "0" COMMENT "pk模式消耗积分",
  `pk_take_percent` int(11) NOT NULL DEFAULT "0" COMMENT "pk每局抽成百分比",
  `add_trophy` int(11) NOT NULL DEFAULT "0" COMMENT "获胜获得奖杯数",
  `less_trophy` int(11) NOT NULL DEFAULT "0" COMMENT "失败扣除奖杯数",
  `pk_cycle` int(11) NOT NULL DEFAULT "0" COMMENT "pk赛季周期 0无 1每月",
  `app_id_account` int(11) NULL COMMENT "项目id，core，语言",
  `mt` int(11) NULL COMMENT "平台 0未知 1iphone 4安卓 9书城",
  `is_has_charge` tinyint(4) NULL COMMENT "是否充过值",
  `corever` int(11) NULL COMMENT "版本号",
  `current_language` int(11) NULL COMMENT "用户当前语言",
  `current_language2` int(11) NULL COMMENT "注册时语言",
  `reg_country` varchar(65533) NULL COMMENT "注册时国家",
  `regdate` datetime NULL COMMENT "用户的注册时间",
  `prod_id` varchar(65533) NULL COMMENT "产品id",
  `device_guid` varchar(65533) NULL COMMENT "设备guid",
  `app_ver` varchar(65533) NULL COMMENT "app版本",
  `ver` int(11) NULL COMMENT "客户端版本号",
  `ads_type` varchar(60) NULL COMMENT "用户广告标签adstype",
  `ads_quality` int(11) NULL COMMENT "用户广告标签",
  `is_negative_user` int(11) NULL COMMENT "是否白嫖用户",
  `etl_tm` datetime NULL COMMENT ""
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `puzzleactuserrecord_id`)
COMMENT "OLAP"
PARTITION BY RANGE(`dt`)
