--
-- Table structure for table `dwd_read_book_read_book_readtime`
--
CREATE TABLE IF NOT EXISTS `dwd_read_book_read_book_readtime` (
  `dt` date NOT NULL COMMENT "根据createtime分区",
  `product_id` smallint(6) NOT NULL COMMENT "产品id",
  `user_id` bigint(20) NOT NULL COMMENT "用户id",
  `book_id` bigint(20) NOT NULL COMMENT "书籍id",
  `data_type` smallint(6) NOT NULL COMMENT "数据来源类型1：书籍粒度的数据，0：章节粒度数据汇总而来",
  `mt` bigint(20) NULL COMMENT "设备类型",
  `appid` int(11) NULL COMMENT "appid",
  `create_time` datetime NULL COMMENT "添加时间",
  `read_time` bigint(20) NULL COMMENT "阅读时长： -s",
  `etl_time` datetime NULL COMMENT "starrocks数据注入时间",
  INDEX index_data_type (`data_type`) USING BITMAP COMMENT '数据来源类型索引'
) ENGINE=OLAP
DUPLICATE KEY(`dt`, `product_id`, `user_id`, `book_id`, `data_type`)
