CREATE TABLE IF NOT EXISTS `dwd_sr_trade_user_refund_order_di` (
  `dt` date NOT NULL COMMENT "日期",
  `ProductId` int(11) NOT NULL COMMENT "产品id",
  `AutoId` bigint(20) NOT NULL COMMENT "自增id",
  `UserId` bigint(20) NULL COMMENT "用户id",
  `PayChannelidId` int(11) NULL COMMENT "支付渠道id",
  `Used` int(11) NULL COMMENT "订单是否处理过 0:未处理 1:处理",
  `OrderId` varchar(128) NULL COMMENT "订单id",
  `status` int(11) NULL COMMENT "订单状态 0 正常订单 1 退款订单",
  `Flag` int(11) NULL COMMENT "标识 0：阅读；1：游戏",
  `CreateTime` datetime NULL COMMENT "发起时间",
  `GetTime` datetime NULL COMMENT "入账时间",
  `ItemCount` int(11) NULL COMMENT "金额数",
  `SystemType` int(11) NULL COMMENT "系统类型",
  `ReceiveDate` datetime NULL COMMENT "被接收时间",
  `MT` int(11) NULL COMMENT "平台",
  `CouponId` varchar(128) NULL COMMENT "优惠券id",
  `PackageId` varchar(255) NULL COMMENT "存放充值页面来源",
  `ShopItem` varchar(128) NULL COMMENT "充值类型（0，普通充值，800，801，802月卡，810vip，830新签到卡)",
  `ExtInfo` varchar(128) NULL COMMENT "扩展字段",
  `VipExpireTime` varchar(20) NULL COMMENT "充值订阅卡时，谷歌和苹果返回的过期时间",
  `RealMoney` int(11) NULL COMMENT "给的阅币数",
  `AwardMoney` int(11) NULL COMMENT "赠送币数量",
  `PayConfigId` int(11) NULL COMMENT "新支付配置id",
  `CoreVer` int(11) NULL COMMENT "core的版本号",
  `DeviceGUID` varchar(255) NULL COMMENT "当前设备id",
  `TestFlag` int(11) NULL COMMENT "是否是测试号充值（0正式，1测试）",
  `BaseAmount` int(11) NULL COMMENT "分成后的数量（除以100为分成后的金额）",
  `Version` varchar(255) NULL COMMENT "购买时，用户客户端的版本号",
  `SubPayType` varchar(50) NULL COMMENT "子支付渠道",
  `GiftMoney` int(11) NULL COMMENT "充值赠送的礼券数(不准确，部分活动赠送未记录)",
  `OrderInitTime` datetime NULL COMMENT "用户订单创建时间",
  `CooOrderExtInfo` varchar(1000) NULL COMMENT "合作方订单扩展",
  `product_data` varchar(1048576) NULL COMMENT "商品数据 发货成功后回写 json格式",
  `refund_time` datetime NULL COMMENT "退款时间",
  `etl_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "etl清洗时间",
  INDEX index_productid (`productid`) USING BITMAP COMMENT 'index_productid'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `ProductId`, `AutoId`)
COMMENT "交易域用户充值事实表"
