  `pre_coin` bigint(20) NULL COMMENT "充值前代币",
  `series_id` bigint(20) NULL COMMENT "剧id",
  `epis_id` bigint(20) NULL COMMENT "剧集id",
  `epis_ids` array<bigint(20)> NULL COMMENT "剧集id(冗余字段，记录一次解锁对应的剧集)",
  `epis_name` varchar(65533) NULL COMMENT "剧集名称",
  `epis_num` bigint(20) NULL COMMENT "集数",
  `platform` varchar(65533) NULL COMMENT "平台",
