--
CREATE TABLE IF NOT EXISTS `dwd_trade_author_translate_remuneration` (
  `dt` date NOT NULL COMMENT "日期,remuneration_time转换而来",
  `auto_id` bigint(20) NOT NULL COMMENT "自增id",
  `to_language` bigint(20) NOT NULL COMMENT "目标语言id",
  `book_id` bigint(20) NOT NULL COMMENT "输出书籍Id",
  `author_id` bigint(20) NOT NULL COMMENT "译员Id",
  `chapter_id` bigint(20) NOT NULL COMMENT "翻译章节Id",
  `author_type` smallint(6) NOT NULL COMMENT "译员类型",
  `role_type` smallint(6) NOT NULL COMMENT "角色类型1：译员、2：外籍一校、3：二校、4：三校、5：PM、6：初译审核、7：初校审核、8：国内测试稿审核、9：国外测试稿审核、10：三校抽查、11：一校抽查、12：质检抽查",
  `pen_name` varchar(65533) NULL COMMENT "译名",
  `real_name` varchar(65533) NULL COMMENT "真名",
  `book_name` varchar(65533) NULL COMMENT "输出书籍名称",
  `chapter_name` varchar(65533) NULL COMMENT "章节名",
  `font_length` bigint(20) NULL COMMENT "字数",
  `price` decimal(18, 4) NOT NULL COMMENT "单价",
  `total_price` decimal(18, 4) NOT NULL COMMENT "稿酬金额",
  `currency_type` smallint(6) NOT NULL COMMENT "货币类型 1：人民币 2：美元",
  `pay_type` bigint(20) NOT NULL COMMENT "支付方式：0：银行卡、1：Paypal、2：Payoneer、3：Upwork、4：Freelancer、5：Fiverr、6：银行卡（华美）",
  `remuneration_time` datetime NOT NULL COMMENT "稿酬生成时间",
  `bill_date` bigint(20) NOT NULL COMMENT "账期",
  `st` smallint(6) NOT NULL COMMENT "状态 0:专员未审核、1：专员待定、2：专员审核通过、3：专员审核拒绝、4：经理审核通过、5：经理审核拒绝、6：财务审核通过、7：财务审核拒绝",
  `pay_st` smallint(6) NOT NULL COMMENT "打款状态 0：待处理、1：已打款、2：不打款",
  `pay_time` datetime NULL COMMENT "打款时间",
  `remark_by_first` varchar(65533) NULL COMMENT "专员审核备注",
  `remark_by_second` varchar(65533) NULL COMMENT "经理审核备注",
  `remark_by_third` varchar(65533) NULL COMMENT "财务审核备注",
  `remark_by_pay` varchar(65533) NULL COMMENT "付款备注",
  `create_time` datetime NULL COMMENT "创建时间",
  `update_time` datetime NULL COMMENT "更新时间",
  `remuneration_type` smallint(6) NULL COMMENT "稿酬类型 1实时稿酬、2附加稿酬、3奖金包",
  `price_type` smallint(6) NULL COMMENT "单价计算方式 1：份数 、2：千字价",
  `source_book_name` varchar(65533) NULL COMMENT "输入书籍名称",
  `from_language` smallint(6) NULL COMMENT "来源语言",
  `source_book_id` bigint(20) NULL COMMENT "输入书籍Id",
  `pay_account` varchar(65533) NULL COMMENT "支付账号",
  `bank_name` varchar(65533) NULL COMMENT "银行名称",
  `account_name` varchar(65533) NULL COMMENT "银行账号名称",
  `reason_type` varchar(65533) NULL COMMENT "附加稿酬原因类型",
  `bank_sub_branch` varchar(65533) NULL COMMENT "银行支行",
  `payment_type` smallint(6) NULL COMMENT "付款方式：0:未选择,1:平台，2：转账",
  `book_type` smallint(6) NULL COMMENT "书籍类型",
  `undo_reason` varchar(65533) NULL COMMENT "撤销原因",
  `admin_Name` varchar(500) NULL COMMENT "用户名",
  `day_target` int(11) NULL COMMENT "日目标",
  `month_target` int(11) NULL COMMENT "月目标",
  `author_name` varchar(500) NULL COMMENT "译员名称",
  `year_month_str` varchar(50) NULL COMMENT "月份(yyyy-mm)",
  `china_workday_flag` varchar(50) NULL COMMENT "是否工作日(周一至周五并且不是中国法定节假日或者节假日前后的补班Y，否则:N)",
  `week_id` int(11) NULL COMMENT "周(202301,周五~周四为一周)",
  `etl_time` datetime NULL COMMENT "数据清洗时间",
  INDEX index_to_language (`to_language`) USING BITMAP COMMENT '目标语言索引'
) ENGINE=OLAP
