  `core` smallint(6) NULL COMMENT "app、包",
  `mt` varchar(65533) NULL COMMENT "mt 端",
  `app_version` varchar(65533) NULL COMMENT "appVersion",
  `step` varchar(65533) NOT NULL COMMENT "标识支付链路的哪个步骤 111110010：点击挡位；111110020：创建订单；111110030：连接谷歌服务时；111110040：调起谷歌支付弹窗时；111110050：谷歌支付返回时；111110060：向谷歌执行消费/确认时；111110070：订单回传时；111111010：对应订单第三方扣款成功，业务奖励发放到账",
  `uuid` varchar(65533) NOT NULL COMMENT "支付链路串联唯一标识 类似tradeid",
  `page_id` varchar(65533) NULL COMMENT "页面ID",
