);

--
-- Table structure for table `dws_consume_book_chapter_ed`
--
CREATE TABLE IF NOT EXISTS `dws_consume_book_chapter_ed` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `site_id` int(11) NOT NULL COMMENT "语言id",
  `book_id` bigint(20) NOT NULL COMMENT "书籍id",
  `chapter_id` bigint(20) NOT NULL COMMENT "章节id",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `types` int(11) NOT NULL COMMENT "1：阅币，2：礼券,3：赠送币,4:vip",
  `corever` int(11) NOT NULL COMMENT "core的版本号",
  `mt` int(11) NOT NULL COMMENT "平台 0未知 1 iphone 4安卓 9书城",
  `ver` int(11) NOT NULL COMMENT "客户端版本号",
  `current_language` int(11) NOT NULL COMMENT "当前语言",
  `current_language2` int(11) NOT NULL COMMENT "注册时语言",
  `reg_date` datetime NOT NULL COMMENT "注册时间保留时分秒",
  `reg_days` int(11) NOT NULL COMMENT "距离注册时间时长",
  `reg_country` varchar(65533) NOT NULL COMMENT "注册国家",
  `appver` varchar(65533) NOT NULL COMMENT "app版本",
  `sex` int(11) NOT NULL COMMENT "性别0未知 1男 2女 3保密",
  `etl_time` datetime NULL COMMENT "数据清洗时间",
  `user_id` bitmap NULL COMMENT "用户id",
  `amound` decimal(18, 6) NULL COMMENT "消费数额",
  INDEX index_product_id (`product_id`) USING BITMAP COMMENT 'index_product_id',
  INDEX index_site_id (`site_id`) USING BITMAP COMMENT 'index_site_id'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `site_id`, `book_id`, `chapter_id`, `product_id`, `types`, `corever`, `mt`, `ver`, `current_language`, `current_language2`, `reg_date`, `reg_days`, `reg_country`, `appver`, `sex`)
