--
-- Table structure for table `dws_consume_short_video_consume_a`
--
CREATE TABLE IF NOT EXISTS `dws_consume_short_video_consume_a` (
  `dt` date NOT NULL COMMENT "日期",
  `product_id` bigint(20) NOT NULL COMMENT "产品id",
  `user_id` bigint(20) NOT NULL COMMENT "用户id",
  `consume_amt_td` decimal(24, 8) NULL COMMENT "累计消耗(代币、赠币)",
  `fst_consume_tm` datetime NULL COMMENT "首次消费时间",
  `lst_consume_tm` datetime NULL COMMENT "最近一次消费时间",
  `consume_cnt_td` bigint(20) NULL COMMENT "累积消费次数",
  `consume_tv_td` bitmap NULL COMMENT "消费剧集bitmap(剧id+集序号)",
  `consume_money_amt_td` decimal(24, 8) NULL COMMENT "累计消耗代币数",
  `fst_consume_money_tm` datetime NULL COMMENT "首次消费代币时间",
  `lst_consume_money_tm` datetime NULL COMMENT "最近一次消费代币时间",
  `consume_money_cnt_td` bigint(20) NULL COMMENT "累积消费代币次数",
  `consume_money_tv_td` bitmap NULL COMMENT "代币消费剧集bitmap(剧id+集序号)",
  `consume_cert_amt_td` decimal(24, 8) NULL COMMENT "累计消耗赠币",
  `fst_consume_cert_tm` datetime NULL COMMENT "首次消费赠币时间",
  `lst_consume_cert_tm` datetime NULL COMMENT "最近一次消费赠币时间",
  `consume_cert_cnt_td` bigint(20) NULL COMMENT "累积消费赠币次数",
  `consume_cert_tv_td` bitmap NULL COMMENT "赠币消费剧集bitmap(剧id+集序号)",
  `etl_time` datetime NULL COMMENT "数据清洗时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `user_id`)
