--
-- Table structure for table `dws_flow_jifen_anditemjifen_give_consume_ed`
--
CREATE TABLE IF NOT EXISTS `dws_flow_jifen_anditemjifen_give_consume_ed` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `user_id` bigint(20) NOT NULL COMMENT "用户id",
  `task_name` varchar(65533) NOT NULL COMMENT "任务名称",
  `corever` int(11) NULL COMMENT "版本号",
  `mt` int(11) NULL COMMENT "平台 0未知 1iphone 4安卓 9书城",
  `app_ver` varchar(65533) NULL COMMENT "app版本",
  `give_points_total` int(11) NULL COMMENT "积分发放数量",
  `consume_points_total` int(11) NULL COMMENT "积分消耗数量",
  `give_coupon_total` int(11) NULL COMMENT "礼券发放数量",
  `expire_coupon_total` int(11) NULL COMMENT "礼券过期",
  `give_item_points_total` int(11) NULL COMMENT "任务积分发放数量",
  `expire_item_points_total` int(11) NULL COMMENT "任务积分过期数量",
  `user_type` int(11) NULL COMMENT "usertype 1IAA 2纯白嫖 3付费白嫖 4非白嫖",
  `etl_tm` datetime NULL COMMENT "创建时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `user_id`, `task_name`)
COMMENT "用户积分用户汇总表"
PARTITION BY RANGE(`dt`)
(

















































PARTITION p202603 VALUES [("2026-03-01"), ("2026-04-01")))
DISTRIBUTED BY HASH(`product_id`, `user_id`) BUCKETS 1
PROPERTIES (
