"bloom_filter_columns" = "user_id",
"dynamic_partition.enable" = "true",
"dynamic_partition.time_unit" = "MONTH",
"dynamic_partition.time_zone" = "Asia/Shanghai",
"dynamic_partition.start" = "-2147483648",
"dynamic_partition.end" = "3",
"dynamic_partition.prefix" = "p",
"dynamic_partition.buckets" = "1",
"dynamic_partition.history_partition_num" = "0",
"dynamic_partition.start_day_of_month" = "1",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

--
-- Table structure for table `dws_flow_operation_oosition_exposure_ed`
--
CREATE TABLE IF NOT EXISTS `dws_flow_operation_oosition_exposure_ed` (
  `dt` date NOT NULL COMMENT "分区日期",
  `product_id` int(11) NULL COMMENT "产品id",
  `user_id` bigint(20) NULL COMMENT "用户id",
  `current_language` int(11) NULL COMMENT "界面语言",
  `current_language2` int(11) NULL COMMENT "注册语言",
  `reg_country` varchar(255) NULL COMMENT "注册国家",
  `country_level` int(11) NULL COMMENT "国家等级",
  `corever` int(11) NULL COMMENT "corever",
  `mt` varchar(255) NULL COMMENT "终端",
  `page_name` varchar(65533) NULL COMMENT "页面名称",
  `page_id` int(11) NULL COMMENT "页面ID",
  `element_name` varchar(65533) NULL COMMENT "控件名称",
  `element_id` int(11) NULL COMMENT "控件ID",
  `activity_id` varchar(65533) NULL COMMENT "活动id",
  `parent_group_id` int(11) NULL COMMENT "用户集合ID",
  `group_id` int(11) NULL COMMENT "用户分组ID(人群包id)",
  `send_id` varchar(65533) NULL COMMENT "转化来源",
  `count_down` bigint(20) NULL COMMENT "倒计时标签时长",
  `event_strategy_id` int(11) NULL COMMENT "策略id",
  `start_type` int(11) NULL COMMENT "0冷启动,1热启动仅开屏控件上报",
  `cnt` int(11) NULL COMMENT "pv次数",
  `etl_tm` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "清洗时间",
  INDEX index_product_id (`product_id`) USING BITMAP COMMENT 'index_product_id',
  INDEX index_page_id (`page_id`) USING BITMAP COMMENT 'index_page_id',
  INDEX index_element_id (`element_id`) USING BITMAP COMMENT 'index_element_id'
) ENGINE=OLAP
DUPLICATE KEY(`dt`, `product_id`, `user_id`)
COMMENT "运营位曝光事件"
