--
-- Table structure for table `dws_read_consume_user_consume_p_hi`
--
CREATE TABLE IF NOT EXISTS `dws_read_consume_user_consume_p_hi` (
  `dt_hour` datetime NOT NULL COMMENT "createtime 分区",
  `md5_key` varchar(65533) NOT NULL COMMENT "kd5 key",
  `product_id` int(11) NULL COMMENT "产品id",
  `user_id` bigint(20) NULL COMMENT "用户ID",
  `types` int(11) NULL COMMENT "1：阅币，2：礼券,3：赠送币,4:vip",
  `pay_type` int(11) NULL COMMENT "付款方式 对应dim_paytype表中类型（注意：paytype<>1103)",
  `site_id` bigint(20) NULL COMMENT "语言id",
  `book_id` bigint(20) NULL COMMENT "书籍ID",
  `chapter_ids` varchar(65533) NULL COMMENT "章节id组，存在多个ID，以【逗号】分割",
  `Chapter_id` varchar(65533) NULL COMMENT "章节id",
  `corever` bigint(20) NULL COMMENT "core的版本号",
  `mt` int(11) NULL COMMENT "平台 0未知 1iphone 4安卓 9书城",
  `ver` bigint(20) NULL COMMENT "客户端版本号",
  `current_language` bigint(20) NULL COMMENT "当前语言",
  `current_language2` bigint(20) NULL COMMENT "注册时语言",
  `reg_date` datetime NULL COMMENT "注册时间",
  `reg_days` bigint(20) NULL COMMENT "距离注册时间时长",
  `reg_country` varchar(65533) NULL COMMENT "注册国家",
  `appver` varchar(65533) NULL COMMENT "app版本",
  `sex` bigint(20) NULL COMMENT "性别0未知 1男 2女 3保密",
  `is_negative_user` smallint(6) NULL COMMENT "是否白嫖用户",
  `ads_type` varchar(60) NULL COMMENT "用户广告标签ADSTYPE",
  `ads_quality` int(11) NULL COMMENT "广告用户质量",
  `app_id` int(11) NULL COMMENT "项目id，core，语言",
  `con_chp_amount` decimal(18, 6) NULL COMMENT "章节消费数额",
  `con_chp_cnt` bigint(20) NULL COMMENT "章节消费次数",
  `con_book_cnt` decimal(18, 6) NULL COMMENT "消费次数，（1/章节个数）,用于统计用户实际消费次数,即对书的消费次数",
  `fst_time` datetime NULL COMMENT "首次消费时间",
  `lst_time` datetime NULL COMMENT "末次消费时间",
  `etl_time` datetime NULL COMMENT "处理时间",
  INDEX index_product_id (`product_id`) USING BITMAP COMMENT '产品id索引',
  INDEX index_types (`types`) USING BITMAP COMMENT '消费类型索引',
  INDEX index_pay_type (`pay_type`) USING BITMAP COMMENT '支付类型汇总索引',
  INDEX index_site_id (`site_id`) USING BITMAP COMMENT '语言id索引'
) ENGINE=OLAP
PRIMARY KEY(`dt_hour`, `md5_key`)
COMMENT "阅读业务--消耗域--用户消耗小时汇总"
PARTITION BY RANGE(`dt_hour`)
