CREATE TABLE IF NOT EXISTS `dws_user_wide_tag_info_ed` (
  `dt` date NOT NULL COMMENT "日期",
  `user_type` smallint(6) NOT NULL COMMENT "用户类型",
  `product_id` bigint(20) NOT NULL COMMENT "产品id",
  `user_id` bigint(20) NOT NULL COMMENT "用户id",
  `user_period` varchar(65533) NULL COMMENT "用户周期",
  `user_value` varchar(65533) NULL COMMENT "用户价值",
  `source` smallint(6) NULL COMMENT "来源",
  `etl_time` datetime NULL COMMENT "数据清洗时间",
  INDEX index_product_id (`product_id`) USING BITMAP COMMENT 'index_product_id',
  INDEX index_user_period (`user_period`) USING BITMAP COMMENT 'index_user_period',
  INDEX index_user_value (`user_value`) USING BITMAP COMMENT 'index_user_value',
  INDEX index_source (`source`) USING BITMAP COMMENT 'index_source'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `user_type`, `product_id`, `user_id`)
