  `NameOnBankAccount` varchar(255) NULL COMMENT "银行账户名称",
  `BankAccountNumber` varchar(255) NULL COMMENT "银行账户号码",
  `SWIFTCode` varchar(255) NULL COMMENT "银行代码",
  `AuthorType` int(11) NOT NULL DEFAULT "0" COMMENT "作者类型",
