--
CREATE EXTERNAL TABLE `ods_sensors_order_pay_process` (
  `rid` varchar(1048576) NULL COMMENT "神策日志唯一id，rid",
  `user_id` bigint(20) NULL COMMENT "用户id",
  `core` smallint(6) NULL COMMENT "app、包",
  `mt` varchar(1048576) NULL COMMENT "mt 端",
  `app_version` varchar(1048576) NULL COMMENT "appVersion",
  `step` varchar(1048576) NULL COMMENT "标识支付链路的哪个步骤 111110010：点击挡位；111110020：创建订单；111110030：连接谷歌服务时；111110040：调起谷歌支付弹窗时；111110050：谷歌支付返回时；111110060：向谷歌执行消费/确认时；111110070：订单回传时；111111010：对应订单第三方扣款成功，业务奖励发放到账",
  `uuid` varchar(1048576) NULL COMMENT "支付链路串联唯一标识 类似tradeid",
  `page_id` varchar(1048576) NULL COMMENT "页面ID",
  `page_name` varchar(1048576) NULL COMMENT "页面名称",
  `item_id` varchar(1048576) NULL COMMENT "档位id-ItemId",
  `recharge_amount` int(11) NULL COMMENT "充值货币金额",
  `present_gift` int(11) NULL COMMENT "赠送货币金额",
  `real_recharge` int(11) NULL COMMENT "支付金额",
  `parent_group_id` varchar(1048576) NULL COMMENT "用户集合ID",
  `group_id` varchar(1048576) NULL COMMENT "用户集合ID",
  `pay_id` varchar(1048576) NULL COMMENT "支付渠道",
  `pay_type` smallint(6) NULL COMMENT "充值类型,充值、订阅",
