  `jump_url` varchar(1048576) NULL COMMENT "订单回传url",
  `is_success` boolean NULL COMMENT "是否成功",
  `error_parameter` varchar(1048576) NULL COMMENT "失败原因",
  `pay_source` varchar(1048576) NULL COMMENT "充值信息",
  `payment_method` varchar(1048576) NULL COMMENT "支付方式，记录用户的充值方式，谷歌支付/苹果支付/三方支付···",
  `recharge_type` varchar(1048576) NULL COMMENT "充值类型,货币/订阅充值、810、820、830",
  `subscription_days` bigint(20) NULL COMMENT "订阅天数",
  `current_coin` int(11) NULL COMMENT "当前账户付费货币余额",
  `current_gift` int(11) NULL COMMENT "当前账户免费货币余额",
  `event_time` datetime NULL COMMENT "事件时间",
  `sr_createtime` datetime NULL COMMENT "数据写入时间",
  `product_id` varchar(1048576) NULL COMMENT "产品id",
  `dt` varchar(1048576) NULL COMMENT "分区"
) ENGINE=HIVE
