  `Amount` int(11) NOT NULL DEFAULT "0" COMMENT "金额,分为单位",
  `GiveAmount` int(11) NULL DEFAULT "0" COMMENT "赠送金额,一般无用了",
  `BankAmount` int(11) NOT NULL DEFAULT "0" COMMENT "银行金额,一般等同于Amount",
  `ShopItem` varchar(65533) NULL DEFAULT "" COMMENT "支付的商品id",
  `ProductId` varchar(65533) NULL DEFAULT "" COMMENT "充值产品编号",
  `PayType` varchar(65533) NULL DEFAULT "" COMMENT "",
  `BankId` varchar(65533) NULL DEFAULT "" COMMENT "",
  `Ext1` varchar(65533) NULL COMMENT "无用",
  `Ext2` varchar(65533) NULL COMMENT "无用",
  `Ext3` varchar(65533) NULL COMMENT "无用",
  `Ext4` varchar(65533) NULL COMMENT "无用",
  `Ext5` varchar(65533) NULL COMMENT "无用",
