  `ShopItemId` int(11) NULL DEFAULT "0" COMMENT "商品Id,配置在后台",
  `CouponId` varchar(65533) NULL DEFAULT "" COMMENT "优惠券Id",
  `PackageId` varchar(65533) NULL DEFAULT "" COMMENT "客户端透传参数,不同场景用途不一样",
  `Phone` varchar(65533) NULL DEFAULT "" COMMENT "",
  `HasNotifyTimes` int(11) NOT NULL DEFAULT "0" COMMENT "",
  `PayConfigId` int(11) NULL DEFAULT "0" COMMENT "",
  `Core` int(11) NOT NULL DEFAULT "1" COMMENT "",
  `BaseAmount` int(11) NOT NULL DEFAULT "0" COMMENT "统计收入金额字段",
  `UniqueGuid` varchar(65533) NULL DEFAULT "" COMMENT "无用",
  `TestFlag` int(11) NOT NULL DEFAULT "0" COMMENT "测试标记1为测试",
  `CooExtStatus` int(11) NOT NULL DEFAULT "0" COMMENT "",
  `CooExtInfo` varchar(65533) NULL COMMENT "无用",
  `BillInfo` varchar(65533) NULL COMMENT "无用",
  `RowUpdateTimestamp` bigint(20) NOT NULL DEFAULT "0" COMMENT "",
  `SubPayType` varchar(65533) NULL COMMENT "子渠道类型",
  `AutoRenewTimes` int(11) NULL COMMENT "续订次数",
  `PromotionId` varchar(65533) NULL DEFAULT "" COMMENT "广告计划ID",
  `ProjectId` varchar(65533) NULL DEFAULT "" COMMENT "project_id",
  `AID` varchar(65533) NULL DEFAULT "" COMMENT "aid",
  `CID` varchar(65533) NULL DEFAULT "" COMMENT "cid",
  `ADID` varchar(65533) NULL DEFAULT "" COMMENT "ad_id",
  `VirtualPayment` int(11) NULL DEFAULT "0" COMMENT "虚拟支付类型(0-商务号支付,1-虚拟支付)",
  `TFID` varchar(65533) NULL DEFAULT "" COMMENT "投放ID",
  `Platform` varchar(65533) NULL DEFAULT "" COMMENT "支付平台：tt | wx",
  `OptionType` int(11) NULL DEFAULT "0" COMMENT "1-金豆,2-会员,3-整剧购买",
  `OptionSnapshotId` varchar(65533) NULL DEFAULT "" COMMENT "充值产品镜像id",
  `OptionAmount` int(11) NULL DEFAULT "0" COMMENT "金豆数量,会员天数",
  `Bonus` int(11) NULL DEFAULT "0" COMMENT "赠送金豆,赠送天数",
