--
-- Table structure for table `ods_tidb_qadata_admobmediationreportbyappver`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_qadata_admobmediationreportbyappver` (
  `dt` date NOT NULL COMMENT "日期，date字段",
  `Id` bigint(20) NOT NULL COMMENT "",
  `DATE` varchar(10) NULL COMMENT "日期",
  `AD_UNIT` varchar(128) NULL COMMENT "广告单元",
  `PLATFORM` varchar(10) NULL COMMENT "APP 终端",
  `AD_SOURCE` varchar(50) NULL COMMENT "广告来源",
  `APP_VERSION_NAME` varchar(50) NULL COMMENT "APP版本号",
  `APP` varchar(128) NULL COMMENT "APP",
  `AD_REQUESTS` int(11) NULL COMMENT "请求的数量。该值是一个整数。",
  `CLICKS` int(11) NULL COMMENT "用户点击广告的次数。该值是一个整数。",
  `ESTIMATED_EARNINGS` bigint(20) NULL COMMENT "AdMob 发布商的估算收入 例如，6.50 美元将表示为 6500000",
