  `MATCHED_REQUESTS` int(11) NULL COMMENT "响应请求而返回广告的次数。该值是一个整数。",
  `MATCH_RATE` double NULL COMMENT "匹配的广告请求与总广告请求的比率。该值是双精度（近似）十进制值。",
  `OBSERVED_ECPM` bigint(20) NULL COMMENT "第三方广告网络的估计平均 eCPM 例如，$2.30 将表示为 2300000",
  `Account` varchar(255) NULL COMMENT "广告账户",
  `CreatedTime` datetime NULL COMMENT "创建时间",
  `UpdatedTime` datetime NULL COMMENT "更新时间",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL COMMENT "sr数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `Id`)
COMMENT "Admob广告收入表"
DISTRIBUTED BY HASH(`dt`, `Id`) BUCKETS 1
PROPERTIES (
"replication_num" = "3",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

