-- Table structure for table `ods_tidb_shuangwen_en_objectbook`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_shuangwen_en_objectbook` (
  `productid` int(11) NOT NULL COMMENT "产品id",
  `Id` int(11) NOT NULL COMMENT "自增id",
  `BookName` varchar(2000) NULL COMMENT "书籍名称",
  `BookId` bigint(20) NULL COMMENT "来源书籍Id",
  `SwBookId` bigint(20) NULL COMMENT "翻译书籍Id",
  `AuthorId` bigint(20) NULL COMMENT "作者Id",
  `CretaeTime` datetime NULL COMMENT "创建时间",
  `GroupId` int(11) NULL COMMENT "",
  `ChapterNum` int(11) NULL COMMENT "",
  `Status` int(11) NULL COMMENT "状态",
  `AuthorName` varchar(2000) NULL COMMENT "作者名称",
  `Coefficient` decimal(18, 2) NULL COMMENT "稿费系数",
  `StartNum` int(11) NULL COMMENT "常规加更",
  `EndNum` int(11) NULL COMMENT "加更上限",
  `Reward` int(11) NULL COMMENT "",
  `CeilingReward` int(11) NULL COMMENT "",
  `ChapterTime` varchar(600) NULL COMMENT "章节发布时间",
  `ChapterTimeNum` int(11) NULL COMMENT "",
  `LadderReward` varchar(2000) NULL COMMENT "",
  `ReceiveGroupId` int(11) NULL COMMENT "",
  `RewardExplain` varchar(2000) NULL COMMENT "",
  `KindleChapterNum` int(11) NULL COMMENT "章节系数",
  `WeekWordCount` int(11) NULL COMMENT "周更单词",
  `BookType` int(11) NULL COMMENT "书籍类型 0 中文图书 1 英文图书",
  `AutomaticStatus` int(11) NULL COMMENT "是否自动发布章节 0 关闭 1 开启",
  `SelfDay` int(11) NULL COMMENT "自校完成天数",
  `ProofreadingDay` int(11) NULL COMMENT "校对延期时间",
  `ForeignProofreadDay` int(11) NULL COMMENT "外校延期时间",
  `LastChapter` int(11) NULL COMMENT "最后发布章节序号",
  `IsRobot` int(11) NULL COMMENT "是否机翻",
  `RobotChapterCount` int(11) NULL COMMENT "机翻章节数",
  `IsRollBack` int(11) NULL COMMENT "是否驳回",
  `RollBackNumber` int(11) NULL COMMENT "最后驳回序号",
  `CommentTime` datetime NULL COMMENT "打赏评论时间",
  `ToLanguage` int(11) NULL COMMENT "输出语言",
  `MachineRatio` decimal(5, 2) NULL COMMENT "机翻修改比例",
  `ModifyRatio` decimal(5, 2) NULL COMMENT "外校修改比例",
  `UnlockFlow` int(11) NULL COMMENT "解锁流程",
  `IsAnewRobot` int(11) NULL COMMENT "是否重新机翻",
  `IsStopUpdate` int(11) NULL COMMENT "是否停更",
  `StopUpdateDay` int(11) NULL COMMENT "停更天数",
  `StopUpdateTime` datetime NULL COMMENT "停更时间",
  `StopUpdatePerformedTime` datetime NULL COMMENT "",
  `FromLanguage` int(11) NULL COMMENT "输入语言",
  `IsCustom` int(11) NULL COMMENT "是否定制文",
  `IsSelf` int(11) NULL COMMENT "是否跳过自校 0不是，1是",
  `SignType` int(11) NULL COMMENT "签约类型",
  `RobotType` int(11) NULL COMMENT "机翻类型0：百度，1谷歌，2chatgpt",
  `IsParagraph` int(11) NULL COMMENT "是否分段",
  `BookCode` varchar(1000) NULL COMMENT "书籍代号",
  `ObjectBookType` int(11) NULL COMMENT "图书书籍类型,0-网文 1-短剧",
  `IsCostRate` int(11) NULL COMMENT "是否计算成本率,0-否 1-是",
  `IsShortVideo` int(11) NULL COMMENT "是否来源短剧",
  `ChapterTotalLength` int(11) NULL COMMENT "是否来源短剧",
  `HasChangeChapter` int(11) NULL COMMENT "章节总数",
  `HasChangeDictionary` int(11) NULL COMMENT "源章节是否变更",
  `FromObjectBookId` int(11) NULL COMMENT "源字典是否变更",
  `Level` int(11) NULL COMMENT "中文剧壳翻译Id",
  `Score` decimal(18, 2) NULL COMMENT "翻译优先级",
  `ModelIds` varchar(1000) NULL COMMENT "机翻评分",
  `HasRefinement` int(11) NULL COMMENT "机翻流程模型",
  `IsRefinement` int(11) NULL COMMENT "是否精修",
  `StoryType` int(11) NULL COMMENT "类型0长篇小说 1短篇小说",
  `IsDictionaryFinish` int(11) NULL COMMENT "是否词典完成",
  `row_update_time` datetime NULL COMMENT "",
  `AiTaskId` bigint(20) NULL COMMENT "词典提取任务Id",
  `IsExtractFinish` int(11) NULL COMMENT "是否提取完成，默认为完成 0未完成，1完成",
  `IsMaterial` int(11) NULL COMMENT "是否素材",
  `IsFinishNotice` int(11) NULL COMMENT "是否完成翻译文案素材通知标识 0否 1是",
  `IsFinishOutTest` int(11) NULL COMMENT "是否完成外测标识 0否 1是",
  `IsIntroduceBook` int(11) NULL COMMENT "是否书名简介翻译书籍 0否  1是",
  `IsIntroduceTask` int(11) NULL COMMENT "是否下单书名简介翻译任务 0否  1是",
  `AutoCollectionStatus` int(11) NULL COMMENT "自动化领稿生效 0生效  1不生效",
  `AiTagStatus` int(11) NULL COMMENT "大模型tag判断状态  0无，1无需处理 2已处理",
  `AiTagTaskId` int(11) NULL COMMENT "大模型tag任务id",
  `ShortVideoCheckStatus` int(11) NULL COMMENT "短剧抽查状态 null无需抽查 0待抽查 1抽查中 2抽查完成",
  `IsWashingTranslate` int(11) NULL COMMENT "是否孵化洗稿翻译 0否  1是",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`productid`, `Id`)
COMMENT "翻译书籍表"
DISTRIBUTED BY HASH(`productid`, `Id`) BUCKETS 3
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "SwBookId",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

