--
-- Table structure for table `ods_book_log_usermoneylog`
--
CREATE TABLE IF NOT EXISTS `ods_book_log_usermoneylog` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `ProductId` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `UserId` bigint(20) NULL COMMENT "用户ID",
  `CreateTime` datetime NULL COMMENT "记录时间",
  `Amount` int(11) NULL COMMENT "消费数额",
  `RemainAmount` int(11) NULL COMMENT "剩余数额",
  `BookId` bigint(20) NULL COMMENT "书籍ID",
  `ChapterIds` varchar(65533) NULL COMMENT "章节id，存在多个ID，以【逗号】分割",
  `ChapterName` varchar(1024) NULL COMMENT "章节名称",
  `PayType` int(11) NULL COMMENT "付款方式 对应dim_paytype表中类型（注意：paytype<>1103)",
  `MT` int(11) NULL COMMENT "平台",
  `Seq` bigint(20) NULL COMMENT "记录序号可与createtime一起用，提取用户首次消费时间",
  `VipType` int(11) NULL COMMENT "vip类型",
  `OriginCoin` int(11) NULL COMMENT "原始金额",
  `VipDisPrice` int(11) NULL COMMENT "打折金额",
  `AppId` int(11) NULL COMMENT "项目id，core，语言",
  `PositionId` varchar(50) NULL COMMENT "埋点id",
  `AppGameId` bigint(20) NULL COMMENT "游戏id",
  `SendId` varchar(255) NULL COMMENT "发送id",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间",
  INDEX index_ProductId (`ProductId`) USING BITMAP COMMENT 'index_ProductId'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `ProductId`, `Id`)
COMMENT "阅币消耗表"
PARTITION BY RANGE(`dt`)
(



























































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































