CREATE TABLE IF NOT EXISTS `ods_sensors_append` (
  `dt` date NOT NULL COMMENT "分区日期",
  `id` varchar(65533) NOT NULL COMMENT "nvl(rid,track_id)",
  `track_id` varchar(65533) NULL COMMENT "唯一追踪ID",
  `rid` varchar(65533) NULL COMMENT "记录ID",
  `event_tm` datetime NULL COMMENT "事件时间",
  `device_id` varchar(65533) NULL COMMENT "设备id",
  `login_id` varchar(65533) NULL COMMENT "登录id",
  `identity_login_id` varchar(65533) NULL COMMENT "identity_login_id",
  `event` varchar(65533) NULL COMMENT "事件",
  `app_core_ver` varchar(65533) NULL COMMENT "core",
  `distinct_id` varchar(65533) NULL COMMENT "distinct_id",
  `app_product_id` varchar(65533) NULL COMMENT "包体ID",
  `lib_version` varchar(65533) NULL COMMENT "SDK版本",
  `app_version` varchar(65533) NULL COMMENT "应用版本",
  `os` varchar(200) NULL COMMENT "操作系统",
  `app_id` varchar(65533) NULL COMMENT "app_id",
  `app_lang_id` varchar(65533) NULL COMMENT "界面语言",
  `event_duration` varchar(65533) NULL COMMENT "事件时长",
  `screen_name` varchar(65533) NULL COMMENT "页面名称",
  `title` varchar(65533) NULL COMMENT "标题",
  `project_id` varchar(65533) NULL COMMENT "项目ID",
  `model` varchar(65533) NULL COMMENT "设备型号",
  `is_first_day` varchar(65533) NULL COMMENT "是否首日访问",
  `manufacturer` varchar(65533) NULL COMMENT "设备制造商",
  `etl_tm` datetime NULL COMMENT "清洗时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `id`)
COMMENT "event=$AppEnd App退出事件"
PARTITION BY date_trunc('day', dt)
DISTRIBUTED BY HASH(`dt`, `id`)
PROPERTIES (
"replication_num" = "3",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "ZSTD"
);

