--
CREATE TABLE IF NOT EXISTS `ods_sensors_production_orderpayprocess` (
  `dt` date NOT NULL COMMENT "分区日期",
  `id` varchar(65533) NOT NULL COMMENT "nvl(rid,track_id)",
  `track_id` varchar(65533) NULL COMMENT "",
  `rid` varchar(65533) NULL COMMENT "记录ID",
  `event_tm` datetime NULL COMMENT "事件时间",
  `device_id` varchar(65533) NULL COMMENT "设备id",
  `login_id` varchar(65533) NULL COMMENT "login_id",
  `identity_login_id` varchar(65533) NULL COMMENT "identity_login_id",
  `device_lang` varchar(65533) NULL COMMENT "设备语言",
  `event` varchar(65533) NULL COMMENT "事件",
  `distinct_id` varchar(65533) NULL COMMENT "distinct_id",
  `identity_user_id` varchar(65533) NULL COMMENT "identity_userid",
  `app_product_id` varchar(65533) NULL COMMENT "包体ID",
  `send_id` varchar(65533) NULL COMMENT "转化来源",
  `app_core_ver` varchar(65533) NULL COMMENT "core",
  `app_channel` varchar(65533) NULL COMMENT "渠道编号",
  `app_product_x` varchar(65533) NULL COMMENT "应用程序ID",
  `app_lang_id` varchar(65533) NULL COMMENT "界面语言",
  `lib_version` varchar(65533) NULL COMMENT "lib_version",
  `app_version` varchar(65533) NULL COMMENT "app_version",
  `user_id` varchar(65533) NULL COMMENT "用户id",
  `appCoreVer` varchar(65533) NULL COMMENT "app、包",
  `mt` varchar(65533) NULL COMMENT "mt 端",
  `step` varchar(65533) NULL COMMENT "标识支付链路的哪个步骤 111110010：点击挡位；111110020：创建订单；111110030：连接谷歌服务时；111110040：调起谷歌支付弹窗时；111110050：谷歌支付返回时；111110060：向谷歌执行消费/确认时；111110070：订单回传时；111111010：对应订单第三方扣款成功，业务奖励发放到账",
  `uuid` varchar(65533) NULL COMMENT "支付链路串联唯一标识 类似tradeid",
  `page_id` varchar(65533) NULL COMMENT "页面ID",
  `page_name` varchar(65533) NULL COMMENT "页面名称",
  `item_id` varchar(65533) NULL COMMENT "档位id-ItemId",
  `recharge_amount` varchar(65533) NULL COMMENT "充值货币金额",
  `present_gift` varchar(65533) NULL COMMENT "赠送货币金额",
  `real_recharge` varchar(65533) NULL COMMENT "支付金额",
  `parent_group_id` varchar(65533) NULL COMMENT "用户集合ID",
  `group_id` varchar(65533) NULL COMMENT "用户集合ID",
  `pay_id` varchar(65533) NULL COMMENT "支付渠道",
  `pay_type` varchar(65533) NULL COMMENT "充值类型,充值、订阅",
  `order_id` varchar(65533) NULL COMMENT "业务订单号id",
  `jump_url` varchar(65533) NULL COMMENT "订单回传url",
  `is_success` varchar(65533) NULL COMMENT "是否成功",
  `error_parameter` varchar(65533) NULL COMMENT "失败原因",
  `pay_source` varchar(65533) NULL COMMENT "充值信息",
  `payment_method` varchar(65533) NULL COMMENT "支付方式，记录用户的充值方式，谷歌支付/苹果支付/三方支付···",
  `recharge_type` varchar(65533) NULL COMMENT "充值类型,货币/订阅充值、810、820、830",
  `subscription_days` varchar(65533) NULL COMMENT "订阅天数",
  `current_coin` varchar(65533) NULL COMMENT "当前账户付费货币余额",
  `current_gift` varchar(65533) NULL COMMENT "当前账户免费货币余额",
  `project_id` varchar(65533) NULL COMMENT "5阅读 8 短剧",
  `etl_tm` datetime NULL COMMENT "清洗时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `id`)
COMMENT "event=orderPayProcess 订单支付"
PARTITION BY RANGE(`dt`)
(















































































































































































































































































































































































PARTITION p20251215 VALUES [("2025-12-15"), ("2025-12-16")))
DISTRIBUTED BY HASH(`dt`, `id`) BUCKETS 1
PROPERTIES (
