--
-- Table structure for table `ods_tidb_readerlog_Log_BookUserRewardLog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_Log_BookUserRewardLog` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `UserId` bigint(20) NULL COMMENT "用户id",
  `BookId` bigint(20) NULL COMMENT "书籍id",
  `TotalMoney` int(11) NULL COMMENT "打赏总阅币数",
  `Money` int(11) NULL COMMENT "打赏阅币数",
  `AwardMoney` int(11) NULL COMMENT "打赏赠送币数",
  `Type` int(11) NULL COMMENT "打赏类型",
  `CreateTime` datetime NULL COMMENT "创建时间",
  `AppId` int(11) NULL COMMENT "应用程序id",
  `Point` int(11) NULL COMMENT "打赏积分数",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `Id`)
COMMENT "用户打赏书籍记录表"
DISTRIBUTED BY HASH(`Id`) BUCKETS 1
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "CreateTime",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

--
-- Table structure for table `ods_tidb_readerlog_Log_GiftConsumeDetailLog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_Log_GiftConsumeDetailLog` (
  `dt` date NOT NULL COMMENT "createtime分区",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `GiftLogId` bigint(20) NULL COMMENT "id(没用)",
  `UserId` bigint(20) NULL COMMENT "用户Id",
  `GiftNum` int(11) NULL COMMENT "礼券数量",
  `IsCharge` int(11) NULL COMMENT "是否充值获得",
  `Source` varchar(65533) NULL COMMENT "来源",
  `SendTime` datetime NULL COMMENT "礼券发放时间",
  `GiftType` int(11) NULL COMMENT "礼券类型 0:礼券 1：赠送币 ",
  `CreateTime` datetime NULL COMMENT "创建时间 ",
  `AppId` int(11) NULL COMMENT "应用程序id ",
  `SourceKey` varchar(65533) NULL COMMENT "来源key ",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间",
  INDEX index_productid (`product_id`) USING BITMAP COMMENT 'index_productid'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `Id`)
COMMENT "阅读-用户礼券消耗明细表，带礼券来源"
PARTITION BY RANGE(`dt`)
