--
-- Table structure for table `ods_tidb_readerlog_Log_InterestTagsShowLog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_Log_InterestTagsShowLog` (
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `UserId` bigint(20) NULL COMMENT "用户id",
  `CreateTime` datetime NOT NULL COMMENT "创建时间",
  `RType` int(11) NULL COMMENT "请求类型 0：弹窗，1：菜单",
  `Result` int(11) NULL COMMENT "结果",
  `Ver` int(11) NULL COMMENT "版本号",
  `UserLimit` int(11) NULL COMMENT "限制参数",
  `StartTime` datetime NULL COMMENT "限制时间",
  `TagsLimitCfgIsNull` int(11) NULL COMMENT "配置是否为空",
  `UserCreateTime` datetime NULL COMMENT "用户创建时间",
  `AppId` int(11) NULL COMMENT "应用程序id",
  `ShowInterestTags` int(11) NULL COMMENT "是否显示过 -1未命中逻辑"
) ENGINE=OLAP
PRIMARY KEY(`product_id`, `Id`)
COMMENT "海阅-兴趣标签日志,author:014217"
DISTRIBUTED BY HASH(`product_id`, `Id`) BUCKETS 6
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "UserId",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"storage_medium" = "SSD",
"compression" = "ZSTD"
);

--
-- Table structure for table `ods_tidb_readerlog_Log_JiFenMonthLog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_Log_JiFenMonthLog` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `UserId` bigint(20) NULL COMMENT "用户id",
  `Op` int(11) NULL COMMENT "操作",
  `Num` int(11) NULL COMMENT "数量",
  `OrginNum` int(11) NULL COMMENT "用户最新积分存量",
  `Remark` varchar(512) NULL COMMENT "备注",
  `MT` int(11) NULL COMMENT "终端",
  `Prodid` varchar(512) NULL COMMENT "产品id 早期用来区分各个app，已经弃用",
  `Smallpt` varchar(512) NULL COMMENT "Smallpt",
  `VIP` int(11) NULL COMMENT "VIP等级",
  `Star` int(11) NULL COMMENT "经验等级",
  `ModType` int(11) NULL COMMENT "积分变化类型",
  `ParamDict` varchar(512) NULL COMMENT "备份字段",
  `CreateTime` datetime NULL COMMENT "创建时间",
  `AppId` int(11) NULL COMMENT "应用程序id",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `Id`)
COMMENT "用户积分明细表"
PARTITION BY RANGE(`dt`)
