--
-- Table structure for table `ods_tidb_readerlog_Log_NewUserSignLog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_Log_NewUserSignLog` (
  `dt` date NOT NULL COMMENT "createtime分区",
  `product_id` int(11) NOT NULL COMMENT "createtime分区",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `UserId` bigint(20) NULL COMMENT "用户id",
  `Gain` int(11) NULL COMMENT "获得礼券数量",
  `type` int(11) NULL COMMENT "签到类型 1:签到 2:补签",
  `CreateTime` datetime NULL COMMENT "创建时间",
  `AppId` int(11) NULL COMMENT "应用程序id",
  `Guid` varchar(500) NULL COMMENT "设备GUID",
  `Mt` int(11) NULL COMMENT "终端",
  `ProdId` varchar(50) NULL COMMENT "X值",
  `FromActionId` varchar(50) NULL COMMENT "执行签到的协议号（接口） 5302表示新福利中心签到的，除了5302就是旧的（其中5233：H5网赚签到，5212：H5网赚之前的签到） ",
  `Days` int(11) NULL COMMENT "签到天数",
  `Days45` int(11) NULL COMMENT "签到天数45",
  `SignRound` int(11) NULL COMMENT "累计签到轮数",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `Id`)
COMMENT "海外阅读-签到记录表(新旧签到都有)"
PARTITION BY RANGE(`dt`)
