--
-- Table structure for table `ods_tidb_readerlog_Log_PushMessageLog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_Log_PushMessageLog` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "Id",
  `CreateTime` datetime NOT NULL COMMENT "插入时间",
  `UserId` bigint(20) NULL COMMENT "用户Id",
  `ProdId` varchar(255) NULL COMMENT "产品ID",
  `MT` int(11) NULL DEFAULT "0" COMMENT "平台",
  `Title` varchar(65533) NULL COMMENT "标题",
  `TokenId` bigint(20) NULL COMMENT "TokenId",
  `Token` varchar(65533) NULL COMMENT "令牌",
  `Body` varchar(65533) NULL COMMENT "内容",
  `Customers` varchar(65533) NULL COMMENT "推送下发参数",
  `Param` varchar(65533) NULL COMMENT "辅助参数",
  `BatchId` bigint(20) NULL COMMENT "批次Id",
  `State` int(11) NULL DEFAULT "0" COMMENT "状态:0未入列1已入列2已出列3已推送4推送失败5token不存在6FCM有效投递7FCM送达8已发站内信",
  `UpdateTime` datetime NULL COMMENT "更新时间",
  `PushResponse` varchar(65533) NULL COMMENT "推送结果",
  `PushType` int(11) NULL DEFAULT "1" COMMENT "推送类型 1常规 2私信",
  `PushTime` datetime NULL COMMENT "计划推送时间",
  `MessageId` varchar(65533) NULL COMMENT "消息 ID 用于标识消息（FCM使用）",
  `TokenType` int(11) NULL COMMENT "0友盟1FCM2华为",
  `TaskType` int(11) NULL DEFAULT "1" COMMENT "任务类型1Tag中台推送2全站推送3召回推送任务4章节更新推送",
  `ImageUrl` varchar(65533) NULL COMMENT "",
  `IsSilent` tinyint(4) NULL COMMENT "",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间",
  INDEX index_productid (`product_id`) USING BITMAP COMMENT 'index_productid',
  INDEX index_State (`State`) USING BITMAP COMMENT 'index_State'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `Id`, `CreateTime`)
COMMENT "push推送日志表"
PARTITION BY RANGE(`dt`)
