--
-- Table structure for table `ods_tidb_readerlog_log_installreferrerlog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_log_installreferrerlog` (
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `CreateTime` datetime NULL COMMENT "活动时间",
  `AppId` int(11) NULL COMMENT "应用程序id",
  `Appver` varchar(255) NULL COMMENT "版本号",
  `Chl` varchar(755) NULL COMMENT "渠道值",
  `Mt` int(11) NULL COMMENT "平台（终端）",
  `Core` int(11) NULL COMMENT "corever包体",
  `RowData` varchar(65533) NULL COMMENT "存放广告信息",
  `DecryptData` varchar(65533) NULL COMMENT "存放广告信息",
  `UniqueCdReaderId` varchar(255) NULL COMMENT "唯一id",
  `CurrentLanguage` int(11) NULL COMMENT "投放语言",
  `SendToAds` int(11) NULL DEFAULT "0" COMMENT "",
  `SdkType` int(11) NULL COMMENT "sdk类型",
  `UacStatus` int(11) NULL COMMENT "uac状态",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`product_id`, `Id`)
