--
-- Table structure for table `ods_tidb_readerlog_log_readtimelog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_log_readtimelog` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "自增id",
  `UserId` bigint(20) NULL COMMENT "用户id",
  `IP` varchar(512) NULL COMMENT "",
  `MT` int(11) NULL COMMENT "终端",
  `IMEI` varchar(512) NULL COMMENT "",
  `IMSI` varchar(512) NULL COMMENT "",
  `MAC` varchar(512) NULL COMMENT "",
  `Ver` int(11) NULL COMMENT "",
  `Chl` varchar(512) NULL COMMENT "",
  `Device` varchar(512) NULL COMMENT "",
  `SW` int(11) NULL COMMENT "",
  `SH` int(11) NULL COMMENT "",
  `DeviceGUID` varchar(512) NULL COMMENT "",
  `Time` int(11) NULL COMMENT "阅读时长 单位秒",
  `BookId` bigint(20) NULL COMMENT "书籍id",
  `CreateTime` datetime NULL COMMENT "时间记录",
  `AppId` int(11) NULL COMMENT "应用程序id",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `product_id`, `Id`)
COMMENT "书籍粒度用户书籍阅读时长记录"
PARTITION BY RANGE(`dt`)
