--
-- Table structure for table `ods_tidb_readerlog_log_realtimegrouplog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_log_realtimegrouplog` (
  `dt` date NOT NULL COMMENT "createtime 分区",
  `Id` bigint(20) NOT NULL COMMENT "",
  `ProductId` int(11) NOT NULL COMMENT "ProductId",
  `UserId` bigint(20) NULL COMMENT "userid",
  `GroupId` int(11) NULL COMMENT "GroupId",
  `OpType` int(11) NULL COMMENT "操作类型 0:入包 3:出包",
  `StartTime` datetime NULL COMMENT "开始时间",
  `EndTime` datetime NULL COMMENT "结束时间",
  `CreateTime` datetime NULL COMMENT "创建时间（入包时间-东八区） createtime来当作入包时间",
  `AppId` int(11) NULL COMMENT "AppId",
  `ParentGroupId` int(11) NULL COMMENT "父人群包Id",
  `GroupType` int(11) NULL COMMENT "0父 1子",
  `HashId` bigint(20) NULL COMMENT "HashId",
  `GroupsDetail` varchar(500) NULL COMMENT "取模明细",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间",
  INDEX index1 (`GroupId`) USING BITMAP COMMENT 'index_productid'
) ENGINE=OLAP
PRIMARY KEY(`dt`, `Id`, `ProductId`)
COMMENT "人群包用户实时数据"
PARTITION BY RANGE(`dt`)
