--
-- Table structure for table `ods_tidb_readerlog_xx_Log_ReInstallLog`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_readerlog_xx_Log_ReInstallLog` (
  `Product_Id` int(11) NOT NULL COMMENT "产品id",
  `Id` bigint(20) NOT NULL COMMENT "编号id",
  `CreateTime` datetime NULL COMMENT "记录时间",
  `AppId` varchar(65533) NULL COMMENT "应用程序id",
  `UserId` int(11) NULL COMMENT "用户id",
  `Core` bigint(20) NULL COMMENT "Core",
  `Mt` int(11) NULL COMMENT "mt",
  `PreAppId` int(11) NULL COMMENT "上一次的AppId",
  `PreCore` int(11) NULL COMMENT "上一次的Core",
  `PreMt` int(11) NULL COMMENT "上一次的mt",
  `UniqueCdReaderId` int(11) NULL COMMENT "设备信息",
  `Status` varchar(65533) NOT NULL COMMENT "Ads使用,判断是否被用过了",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
