  `FirstLpInitialization` int(11) NOT NULL DEFAULT "0" COMMENT "初始化界面展示次数(isretry=0)只计算首次",
  `ExtidLpClicks` int(11) NOT NULL DEFAULT "0" COMMENT "点击次数(增加了extid的去重)",
