  `ExtidLpInitialization` int(11) NOT NULL DEFAULT "0" COMMENT "初始化界面展示次数(增加了extid的去重)",
  `sr_createtime` datetime NULL COMMENT "",
  `sr_updatetime` datetime NULL COMMENT ""
) ENGINE=OLAP
PRIMARY KEY(`Id`)
COMMENT "广告每日国家(分时区)级别Lp信息"
