);

--
-- Table structure for table `ods_bigdata_ab_experiment_log`
--
CREATE TABLE IF NOT EXISTS `ods_bigdata_ab_experiment_log` (
  `id` bigint(20) NOT NULL COMMENT "ID",
  `experiment_id` bigint(20) NULL COMMENT "实验表id",
  `product_id` bigint(20) NULL COMMENT "",
  `ab_hash_key` varchar(755) NULL COMMENT "",
  `version` bigint(20) NULL COMMENT "",
  `experiment_name` varchar(384) NULL COMMENT "实验名称",
  `experiment_description` varchar(65533) NULL COMMENT "实验描述",
  `experiment_tags` varchar(384) NULL COMMENT "实验标签",
  `experiment_duration` int(11) NULL COMMENT "实验时长",
  `experiment_traffic` double NULL COMMENT "实验流量",
  `traffic_exclusivity` smallint(6) NULL COMMENT "流量是否互斥",
  `traffic_activation_method` smallint(6) NULL COMMENT "流量生效方式",
  `status` smallint(6) NULL COMMENT "实验状态",
  `start_time` datetime NULL COMMENT "启动时间",
  `end_time` datetime NULL COMMENT "结束时间",
  `debug_progress` smallint(6) NULL COMMENT "调试进度",
  `experiment_audience` varchar(65533) NULL COMMENT "",
  `experiment_owners` varchar(65533) NULL COMMENT "",
  `experiment_metrics` varchar(65533) NULL COMMENT "",
  `experiment_versions` varchar(65533) NULL COMMENT "",
  `create_time` datetime NULL COMMENT "创建时间",
  `create_user` varchar(384) NULL COMMENT "创建人",
  `update_time` datetime NULL COMMENT "更新时间",
  `update_user` varchar(384) NULL COMMENT "更新人",
  `log_time` datetime NULL COMMENT "",
  `has_warning` smallint(6) NULL COMMENT "实验是否已告警 1-以告警 0-未告警",
  `sr_createtime` datetime NULL COMMENT "",
  `sr_updatetime` datetime NULL COMMENT ""
) ENGINE=OLAP
PRIMARY KEY(`id`)
COMMENT "AB测试实验日志表"
DISTRIBUTED BY HASH(`id`) BUCKETS 5
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "experiment_id, version",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

--
-- Table structure for table `ods_book_novel_book_m`
--
CREATE TABLE IF NOT EXISTS `ods_book_novel_book_m` (
  `productid` int(11) NOT NULL COMMENT "产品id",
  `BookID` bigint(20) NOT NULL COMMENT "书籍id",
  `yt` date NOT NULL COMMENT "BuildTime年分区",
  `SiteID` int(11) NULL COMMENT "语言id",
  `CID` int(11) NULL COMMENT "分类id",
  `CName` varchar(100) NULL COMMENT "分类名称",
  `BookName` varchar(100) NULL COMMENT "书名",
  `AuthorName` varchar(100) NULL COMMENT "作者名字",
  `Length` int(11) NULL COMMENT "书籍字数",
  `UpdateTime` datetime NULL COMMENT "更新时间",
  `LatestUpdateTime` datetime NULL COMMENT "章节最新更新时间",
  `UpdateChapterID` bigint(20) NULL COMMENT "最后更新的章节Id",
  `UpdateChapterName` varchar(512) NULL COMMENT "更新后章节名字",
  `LatestUpdateChapterName` varchar(512) NULL COMMENT "最新更新的章节名字",
  `ImgSrc` varchar(250) NULL COMMENT "图片地址(和阅读)",
  `Introduce` varchar(65533) NULL COMMENT "简介",
  `Status` int(11) NULL COMMENT "书籍状态",
  `BuildTime` datetime NULL COMMENT "书籍上传时间",
  `normalchapternum` int(11) NULL COMMENT "章节数",
  `vipchapternum` int(11) NOT NULL COMMENT "出版图书总章节数",
  `normalchapternum_f` int(11) NULL COMMENT "发布章节数",
  `vipchapternum_f` int(11) NOT NULL COMMENT "出版图书总章节数",
  `CollectCount` int(11) NOT NULL COMMENT "vip章节数",
  `AuthorID` bigint(20) NOT NULL COMMENT "作者Id",
  `Size` int(11) NOT NULL COMMENT "大小",
  `isFull` int(11) NULL COMMENT "完本状态 0连载 1合作商通知完本 3完本打包队列 4打包成功 5打包失败 6完本不打包 7图书打包",
  `Channel` int(11) NULL COMMENT "渠道",
  `PricePerThousand` int(11) NOT NULL COMMENT "千字价",
  `Source` int(11) NOT NULL COMMENT "来源 0:盗版 1:正版",
  `NewCID` int(11) NULL COMMENT "分类id",
  `NewCName` varchar(100) NULL COMMENT "分类名称",
  `Sexy2` int(11) NULL COMMENT "涉黄等级",
  `FullPrice` int(11) NULL COMMENT "完本价格",
  `VoiceChapterNum` int(11) NOT NULL COMMENT "音频章节数目",
  `url` varchar(512) NULL COMMENT "百度百科链接地址",
  `isEpub` tinyint(4) NULL COMMENT "是否为出版图书",
  `epub_path` varchar(500) NULL COMMENT "出版图书下载地址",
  `epub_price` int(11) NULL COMMENT "出版图书价格(阅币)",
  `FreeChapterNum` int(11) NULL COMMENT "免费章节数",
  `BookNo` bigint(20) NOT NULL COMMENT "书号",
  `VoiceBookId` bigint(20) NULL COMMENT "关联有声书籍Id",
  `IsEighteen` tinyint(4) NOT NULL COMMENT "是否18禁",
  `Alias` varchar(500) NULL COMMENT "Tag列表",
  `NCartoonId` bigint(20) NULL COMMENT "漫画id",
  `VCartoonId` bigint(20) NULL COMMENT "有声漫画id",
  `Translator` varchar(255) NULL COMMENT "翻译者",
  `Verifier` varchar(255) NULL COMMENT "校验者",
  `ChapterGiftBuyHour` int(11) NOT NULL COMMENT "",
  `KeyWord` varchar(2000) NULL COMMENT "SEO关键字",
  `TitleWord` varchar(2000) NULL COMMENT "SEO标题",
  `DescriptionWord` varchar(2000) NULL COMMENT "SEO描述",
  `Language` int(11) NULL COMMENT "语言",
  `FullTime` datetime NULL COMMENT "完本时间",
  `BookNature` tinyint(4) NOT NULL COMMENT "书籍类型",
  `IsStop` tinyint(4) NOT NULL COMMENT "是否停更",
  `StopTime` datetime NULL COMMENT "停更时间",
  `SignType` int(11) NULL COMMENT "签约状态",
  `StoryType` int(11) NULL COMMENT "类型  0长篇小说 1短篇小说",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间",
  INDEX index_productid (`productid`) USING BITMAP COMMENT 'index_productid',
  INDEX index_siteid (`SiteID`) USING BITMAP COMMENT 'index_siteid'
) ENGINE=OLAP
PRIMARY KEY(`productid`, `BookID`)
COMMENT "readernovel书籍信息表"
DISTRIBUTED BY HASH(`productid`, `BookID`) BUCKETS 20
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "BookID, BuildTime",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

--
-- Table structure for table `ods_book_novel_chaptersync`
--
CREATE TABLE IF NOT EXISTS `ods_book_novel_chaptersync` (
  `yt` date NOT NULL COMMENT "create_time按年分区",
  `AutoId` bigint(20) NOT NULL COMMENT "自增id",
  `chapter_id` bigint(20) NOT NULL COMMENT "章节id",
  `book_id` bigint(20) NOT NULL COMMENT "书籍id",
  `chapter_name` varchar(65533) NOT NULL COMMENT "章节名称",
  `chapter_length` int(11) NOT NULL COMMENT "章节字数",
  `chapter_content` varchar(65533) NOT NULL COMMENT "章节内容",
  `status` int(11) NOT NULL COMMENT "状态",
  `vip` int(11) NOT NULL COMMENT "是否vip",
  `create_time` datetime NOT NULL COMMENT "创建时间",
  `update_time` datetime NOT NULL COMMENT "更新时间",
  `timer` datetime NULL COMMENT "更新时间（例如章节字数有发生变化，时间会更新）",
  `public_time` datetime NULL COMMENT "更新时间",
  `serial_number` int(11) NOT NULL COMMENT "章节序号",
  `m_flag` int(11) NOT NULL COMMENT "没用字段",
  `site_id` int(11) NOT NULL COMMENT "书籍id",
  `is_lock` int(11) NULL COMMENT "没用字段",
  `IsSyncFt` int(11) NULL COMMENT "是否同步",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间",
  INDEX index_bookid (`book_id`) USING BITMAP COMMENT '书籍id索引'
) ENGINE=OLAP
PRIMARY KEY(`yt`, `AutoId`)
COMMENT "繁体书籍章节信息表-按年分区"
DISTRIBUTED BY HASH(`yt`, `AutoId`) BUCKETS 15
PROPERTIES (
"replication_num" = "3",
"bloom_filter_columns" = "create_time, book_id",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

