--
-- Table structure for table `ods_tidb_sharpengine_ads_global_FbAdRoiInstallReferrerVideo`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_sharpengine_ads_global_FbAdRoiInstallReferrerVideo` (
  `Id` int(11) NOT NULL COMMENT "id",
  `AdId` varchar(65533) NULL COMMENT "广告id",
  `CreateTime` varchar(65533) NULL COMMENT "创建时间",
  `PayList` varchar(65533) NULL COMMENT "充值信息",
  `RegNum` int(11) NULL COMMENT "注册数",
  `CostAmount` decimal(10, 2) NULL COMMENT "成本",
  `ProductId` int(11) NULL COMMENT "产品id",
  `PayNum` int(11) NULL COMMENT "充值数",
  `RePayUserNum` int(11) NULL COMMENT "复充人数,充值次数>1的人数",
  `UpdateTime` datetime NULL COMMENT "更新时间",
  `PayListByDays` varchar(65533) NULL COMMENT "充值信息列表",
  `CheckSum` bigint(20) NULL COMMENT "检查总数",
  `LoginNum2` int(11) NULL COMMENT "D2登录数",
  `LoginNum3` int(11) NULL COMMENT "D3登录数",
  `LoginNum7` int(11) NULL COMMENT "D7登录数",
  `Core` int(11) NULL COMMENT "core",
  `Mt` int(11) NULL COMMENT "设备类型",
