CREATE TABLE IF NOT EXISTS `ads_trade_user_type_ltv_mid` (
  `dt` date NOT NULL COMMENT "日期,来自stat_period",
  `user_period` int(11) NOT NULL COMMENT "用户类型 1：新用户 3：rmt(拉活用户)",
  `product_id` int(11) NOT NULL COMMENT "产品id",
  `user_id` varchar(65533) NOT NULL COMMENT "用户id",
  `pay_days` int(11) NOT NULL COMMENT "时间差，支付时间与（注册时间，活跃时间，rmt时间差）",
  `which_weeks` int(11) NULL COMMENT "第几周",
