--
-- Table structure for table `ads_bi_sr_recharge_user_detail_di`
--
CREATE TABLE IF NOT EXISTS `ads_bi_sr_recharge_user_detail_di` (
  `dt` date NOT NULL COMMENT "日期分区",
  `period_type` varchar(50) NOT NULL COMMENT "周期类型",
  `event_strategy_id` varchar(200) NOT NULL COMMENT "策略ID",
  `recharge_source` varchar(200) NOT NULL COMMENT "充值来源",
  `user_id` bigint(20) NOT NULL COMMENT "用户id",
  `mt` varchar(50) NOT NULL COMMENT "终端",
  `corever` varchar(50) NOT NULL COMMENT "core",
  `row_1` int(11) NOT NULL COMMENT "排序",
  `shop_item_type` varchar(500) NULL COMMENT "档位类型",
  `item_count` varchar(500) NULL COMMENT "充值档位",
  `item_type` varchar(500) NULL COMMENT "充值商品周期类型",
  `subpay_type` varchar(500) NULL COMMENT "充值渠道类型",
  `strategy_name` varchar(200) NULL COMMENT "策略名称",
  `user_type` varchar(200) NULL COMMENT "用户类型",
  `put_language` varchar(50) NULL COMMENT "投放语言",
  `country_level` varchar(50) NULL COMMENT "国家等级",
  `exposure_pv` int(11) NULL COMMENT "曝光PV",
  `ad_exposure_pv` int(11) NULL COMMENT "广告曝光PV",
  `recharge_user_id` bigint(20) NULL COMMENT "充值用户id",
  `recharge_amount` decimal(12, 2) NULL COMMENT "充值金额",
  `recharge_order_num` int(11) NULL COMMENT "充值成功订单数",
  `create_order_num` int(11) NULL COMMENT "创建订单数",
  `finish_time` int(11) NULL COMMENT "订单完成用时(秒)",
  `ad_amount` decimal(12, 6) NULL COMMENT "广告收益",
  `package_id` varchar(65533) NULL COMMENT "",
  `SensorsData` varchar(65533) NULL COMMENT "",
  `exp_element_id` varchar(500) NULL COMMENT "",
  `etl_ime` datetime NULL COMMENT "清洗时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `period_type`, `event_strategy_id`, `recharge_source`, `user_id`, `mt`, `corever`, `row_1`)
COMMENT "海阅用户充值明细报表"
PARTITION BY time_slice(dt, 7, 'day', 'floor')
DISTRIBUTED BY HASH(`dt`, `event_strategy_id`, `user_id`) BUCKETS 3
PROPERTIES (
"replication_num" = "3",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

