-- Table structure for table `ods_tidb_short_video_push_center_push_arrived_message`
--
CREATE TABLE IF NOT EXISTS `ods_tidb_short_video_push_center_push_arrived_message` (
  `dt` date NOT NULL COMMENT "日期",
  `id` bigint(20) NOT NULL COMMENT "主键id",
  `core` varchar(6) NOT NULL COMMENT "core",
  `event_timestamp` datetime NULL COMMENT "服务器记录的事件时间戳,东八区",
  `project_number` bigint(20) NULL COMMENT "发送消息的项目的唯一编号",
  `message_id` varchar(765) NULL COMMENT "消息id用于标识消息。消息 id 根据应用 id 和时间戳生成，在某些情况下可能不是全局唯一的。",
  `instance_id` varchar(765) NULL COMMENT "消息发送到的应用的唯一 id,如有,它可以是实例 id 或 firebase 安装 id。",
  `message_type` varchar(300) NULL COMMENT "消息的类型。可以是通知消息或数据消息。主题用于标识主题或广告系列发送的原始消息；后续消息则为通知消息或数据消息。",
  `sdk_platform` varchar(300) NULL COMMENT "接收消息的应用所在的平台",
  `app_name` varchar(300) NULL COMMENT "android 应用的软件包名称或 ios 应用的软件包 id",
  `collapse_key` varchar(600) NULL COMMENT "标识一组可折叠消息的折叠键。若未连接设备，则仅具有给定折叠键的最后一条消息将排队等待最终传送",
  `priority` int(11) NULL COMMENT "消息的优先级。有效值包括normal（普通）和high（高）。在 ios 中，这些值相当于 apns 优先级中的 5 和 10",
  `ttl` int(11) NULL COMMENT "此参数指定设备离线后消息在 fcm 存储中保留的时长（以秒为单位）",
  `topic` varchar(300) NULL COMMENT "消息发送到的主题的名称,如有",
  `bulk_id` bigint(20) NULL COMMENT "标识一组相关消息的批量 id,例如向某个特定主题发送的一组消息",
  `event` varchar(300) NULL COMMENT "事件的类型。可能的值包括：message_accepted：fcm 服务器收到了消息，且请求有效；message_delivered：消息已发送到设备上的应用的 fcm sdk。默认情况下，此字段不会被传播。如需启用，请按照 setdeliverymetricsexporttobigquery，boolean 中的说明操作。missing_registrations：由于注册缺失，请求被拒绝；unauthorized_registration：消息被拒绝，因为发送者无权向注册发送消息；message_received_internal_error：处理消息请求时发生不明错误；mismatch_sender_id：由于发送消息的发送者 id 与声明的端点 id 消息不匹配，发送消息的请求被拒绝；quota_exceeded：由于配额不足，发送消息的请求被拒绝；invalid_registration：由于注册无效，发送消息的请求被拒绝；invalid_package_name：由于软件包的名称无效，发送消息的请求被拒绝；invalid_apns_credential：由于 apns 证书无效，发送消息的请求被拒绝；invalid_p",
  `analytics_label` varchar(765) NULL COMMENT "使用 http v1 api 时，可以在发送消息时设置分析标签，以便标记消息以供分析之用",
  `create_time` datetime NULL COMMENT "数据创建时间",
  `is_delete` tinyint(4) NULL DEFAULT "0" COMMENT "删除状态: 1是0否",
  `sr_createtime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据注入时间",
  `sr_updatetime` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT "starrocks数据更新时间"
) ENGINE=OLAP
PRIMARY KEY(`dt`, `id`, `core`)
COMMENT "推送消息到达状态记录表"
PARTITION BY RANGE(`dt`)
(














































PARTITION p20251215 VALUES [("2025-12-15"), ("2025-12-16")))
DISTRIBUTED BY HASH(`dt`, `core`)
PROPERTIES (
"replication_num" = "3",
"dynamic_partition.enable" = "true",
"dynamic_partition.time_unit" = "day",
"dynamic_partition.time_zone" = "Asia/Shanghai",
"dynamic_partition.start" = "-45",
"dynamic_partition.end" = "3",
"dynamic_partition.prefix" = "p",
"dynamic_partition.history_partition_num" = "0",
"in_memory" = "false",
"enable_persistent_index" = "true",
"replicated_storage" = "true",
"compression" = "LZ4"
);

